quests[1052] = { id = 1052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Scarlet Path", description = "We of the Scarlet Crusade lay claim to strongholds from Hearthglen to Tirisfal Glades. We are quite proud of our bastions of cleansing throughout Lordaeron.\n\nYou have proven yourself against the undead in Desolace. But the true threat of the plague lies in Lordaeron.\n\nTravel to the town of Southshore, in the Eastern Kingdoms. Seek out a crusader named Raleigh the Devout. Give him this letter of commendation bearing my seal and he will escort you to a place of honor in our Scarlet Monastery.", progress = "Who goes there? What do you want from me?", completion = "Brother Anton still spreads the word of the Scarlet Crusade? Oh my....", objectives = "Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1053] = { id = 1053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Name of the Light", description = "I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead.\n\nBut as I spent time at the Monastery in Tirisfal Glades I realized that their grasp on reality was slipping. They now think everyone is plagued who doesn't wear the tabard of the Crusade. Innocent men and women were tortured because they were supposedly plagued. \n\nThe Scarlet Crusade must be crushed in the name of the Light. You, {name}, must destroy the deranged regime.", completion = "While disciples of the Light never revel in the loss of life, we must accept that on occasion, such sacrifices must happen for the greater good of the Kingdom and the planet.\n\nThrough your deeds in the Monastery you have spared many innocent lives, {name}. I salute your tenacity.", objectives = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1054] = { id = 1054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Threat", description = "Directly to the north of Astranaar are the Thistlefur furbolg. My scouts report that their numbers have grown greatly over the past few months. If they grow too great, they may find the courage to attack Astranaar directly.\n\nKill as many of their kind as you can, but bring me their chieftain's skull as proof that their efforts have been stifled... for now.\n\nI shall remain here in Astranaar and await word from you. Elune be with you.", progress = "The furbolgs' corruption has caused Ashenvale to become a fraction of its former glory.", completion = "Well done, {name}.\n\nWe are under constant threat from the furbolg. Hopefully this will keep them at bay for a bit longer.", objectives = "Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1055] = { id = 1055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "The rod, now complete, lies in your hands. Shael'dryn will want to hear of your success.", sourceObjective = "Return to Shael'dryn at the moonwell.", completion = "You've done it, {name}! Well done!", sourceObjectiveStatus = "unverified-source-field" }
quests[1056] = { id = 1056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Stonetalon Peak", description = "The forest spirits tell me you are brave and willing to travel.\n\nTo the south, not far from Mystral Lake, there lies a tunnel named The Talondeep Path. Through this tunnel you will come to an area known as Windshear Crag in the Stonetalon Mountains. Once there, journey to the southwest past Cragpool Lake and then north, up the steep slope until you reach Stonetalon Peak.\n\nThere awaits Keeper Albagorm. Heed his bidding, {race}.\n\nThe journey will be perilous.", sourceObjective = "Travel to Keeper Albagorm on Stonetalon Peak.", completion = "Finally, you arrive. I see Faldreas has listened to the forest spirits....", sourceObjectiveStatus = "unverified-source-field" }
quests[1057] = { id = 1057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Charred Vale", description = "As a protector of the forest spirits you can undoubtedly guess why I am alarmed.\n\nYou have traveled through these mountains to reach this peak. Surely you have seen the travesty which has befallen the land. Greed has led to the destruction of these sacred hills.\n\nThe Charred Vale to the south was set afire by the greedy mechanized army of industrialists. Worse yet, the Bloodfuries that have encroached on the land refuse us passage in to begin regrowth.\n\nDrive the wretched harpies out, {name}!", completion = "Now that the Bloodfuries have suffered such a great loss, perhaps the true work of restoring the land can begin....", objectives = "Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1058] = { id = 1058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'Zil's Forest Magic", description = "So excited I am!\n\nThree little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of... what do they call it... forest magic!\n\nI'll need a good mess of Stonetalon sap. From those horrid felines, bring me some twilight whiskers. This calls for plenty of courser eyes, of course -- can never have enough eyes. Oh, and lest we forget, a precious scale from a fey dragon.\n\nHurry to Stonetalon Peak, {name}, so I can brew some forest magic!", progress = "Look at our poor little elf friends. All caged up with no forest to frolic in!\n\nNow were you able to find me some sap? How about the whiskers from the twilight runners? Don't suppose you have that fey dragon scale on you?\n\nAnd eyes! I'll need so many eyes! You just can't mix up a fierce forest magic brew without a good helping of eyes!", completion = "Oh how happy these little woodland nymphs shall be! We'll make them feel right at home with this special concoction!", objectives = "Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1059] = { id = 1059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Charred Vale", description = "The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken.\n\nFar south of the Barrens lies a land known as Thousand Needles. If you travel west in Thousand Needles until you reach the lush forest's edge of Feralas, you will find a druid named Falfindel Waywarder.\n\nThis great and wise druid is capable of calling forth great forest spirits which can aid in the reclamation of the Charred Vale.\n\nSend word of our need! Seek him out at once!", sourceObjective = "Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.", completion = "Keeper Albagorm was wise to send you with such urgency.\n\nLet us see if we cannot call forth aid from the great forest to travel to the Charred Vale before it is too late.", sourceObjectiveStatus = "unverified-source-field" }
quests[1060] = { id = 1060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "etter to Jin'Zil", description = "You've done so well for me, {name}. You're a regular lucky rabbit's foot and there's something I want you to see.\n\nThe harpies are not from around the Barrens. They come from a place called Stonetalon, far to the northwest of here. Though it is probably a dangerous place for you, I need this letter delivered to an old friend of mine who lives there, a witch doctor by the name of Jin'Zil.\n\nHe'll be happy to know that Serena Bloodfeather is dead, and I think you'll find Stonetalon an interesting place.", progress = "You seem a shady character. You have something for me to see?", completion = "Ahh, a letter from Darsok. I have not heard from him in many years.\n\nSo the last of the Bloodfeathers are dead, eh? That is good news, I can remember when my friend Rokhan went with that crazy mok'nathal to kill her older sister. Ah, to be young again, like you.", objectives = "Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1061] = { id = 1061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirits of Stonetalon", description = "The spirits of the Stonetalon Mountains are angered, for goblins and their servants are plundering and burning the land.  So the land has cried out, and those who listen for such things... have heard.\n\nSeereth Stonebreak, a promising shaman of the Horde, was sent to Stonetalon.  She reports massive deforestation at the hands of the goblins, and requests aid.\n\nMeet Seereth in Stonetalon.  To reach her, follow the road west of the Barrens' Crossroads.  She is camped near the Greatwood Vale.", completion = "Ah, a {class}.  Very good.  We will need your skills to deal with these plunderers!", objectives = "Speak with Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1062] = { id = 1062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Invaders", description = "The goblin-run Venture Company moved into the Stonetalon Mountains, chopping down trees and burning huge stretches of forest.  The spirits of this place are nearly blind with pain and rage.  We must stop the Venture Company!\n\nHead northwest, beyond the Greatwood Vale and into the Windshear Crag.  You will find the goblins and their servants at work--show them the Horde will not allow the exploitation of Stonetalon.  Show them in the language they best understand...\n\nViolence.", completion = "Bravely done, {name}.\n\nWe may ultimately need the wisdom of tauren elders to calm the spirits of Stonetalon, but...\n\nRidding the Venture Company of its personnel is a good first move against them.", objectives = "Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1063] = { id = 1063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elder Crone", description = "To truly tend the spirits of Stonetalon we must consult the tauren elders.\n\nI do not know many of their leaders' names, but I do know of one: Magatha.  I have heard that she is very old, and she knows much.  If anyone can marshal spiritual aid from the tauren, it is she.\n\nMagatha resides in the tauren capital of Thunder Bluff, on Elder Rise -- the city's northeastern bluff.  Speak with Magatha, and tell her of the peril of Stonetalon Mountains.", completion = "I bid you greetings.  You are here seeking counsel?", objectives = "Speak with Magatha in Thunder Bluff.To truly tend the spirits of Stonetalon we must consult the tauren elders.\n\nI do not know many of their leaders' names, but I do know of one: Magatha. I have heard that she is very old, and she knows much. If anyone can marshal spiritual aid from the tauren, it is she.\n\nMagatha resides in the tauren capital of Thunder Bluff, on Elder Rise -- the city's northeastern bluff. Speak with Magatha, and tell her of the peril of Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1064] = { id = 1064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forsaken Aid", description = "The tauren have a bond with the land, and it pains me to hear of Stonetalon's plight.  But I fear that to heal the land, we must first remove the disease upon it.\n\nIs it not fortunate, then, that the Forsaken are allied with us?  They know much of disease.  I believe they can aid us, and by doing so they will strengthen the trust between our people.\n\nSpeak with Apothecary Zamah.  She is a scholar and an emissary of the Forsaken.  You will find her in the Pools of Vision below the Spirit Rise.", completion = "Magatha sent word of your coming, {name}.  Although my heart beats no longer, I still feel sorrow for the spirits of Stonetalon.\n\nThe Forsaken are eager to offer what help we can.", objectives = "Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1065] = { id = 1065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Tarren Mill", description = "To rid Stonetalon of the Venture Company, we must take extreme measures.  Extreme, but without bloodshed.\n\nA colleague of mine may have just the tool we need.  His name is Lydon; he dwells in the town of Tarren Mill in the Hillsbrad Foothills, in the distant land of Lordaeron.\n\nTo reach Hillsbrad, travel by zeppelin to our capital, the Undercity.  Then go north to Tirisfal Glades, southwest to Silverpine, and south to Hillsbrad.\n\nSeek Lydon and bring him this note.  It details our needs to him.", progress = "Ah, are you here with my new test subjects?", completion = "A note from Zamah?  Her needs must be great to send word from so far.  Let us see what she says...\n\nAh, splendid!  I know exactly what to do!", objectives = "Bring Zamah's Note to Apothecary Lydon in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1066] = { id = 1066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of Innocents", description = "I will create a toxin to bleed the violence from the Venture Company, rendering them weak and docile.  That should fix the Horde's problem in Stonetalon, yes?\n\nBut to create the toxin, I will need the blood of innocents, a difficult ingredient to obtain.\n\nFortunately the Syndicate, a group of human brigands in this area, employ shadow mages... and those mages collect innocent blood for their own, unsavory purposes.\n\nYou can find the Syndicate shadow mages in Durnholde Keep to the southeast.", progress = "Did you find the Syndicate Shadow Mages, and collect from them the blood?", completion = "Very good!  I trust the Syndicate gave you little trouble?\n\nAs I mentioned, the blood of innocents is not an easy thing to obtain.  We are lucky the Syndicate shadow mages did the difficult work for us.\n\nNow hold a moment while I create my concoction...", objectives = "Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1067] = { id = 1067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Thunder Bluff", description = "Here is the toxin.  If you use it against the Venture Company it should produce favorable, perhaps even contagious, results.  I must say, it is quite exciting to see my work applied in the field!\n\nBut before using it, take it to Apothecary Zamah.  She must create a delivery method for the toxin to maximize its effect.", progress = "You have returned, {name}.  Do you bring aid from Apothecary Lydon?", completion = "A toxin from Apothecary Lydon?  Very good.  If I know Lydon, then this toxin will be quite effective against the Venture Company...", objectives = "Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1068] = { id = 1068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredding Machines", description = "There is a relation to the spiritual magic of shaman and the natural magic of druids.  This is why we shaman can hear the plea of the spirits of Stonetalon.  Many of their whisperings are lost to me, but one message, one vision, is clear...\n\nI saw a vision of two man-shaped machines in Windshear Crag, northwest of Greatwood Vale, felling trees with impossible speed.  These metal beasts must be stopped!\n\nIn my vision, the machines were marked with strange symbols:\n\nXT:4 and XT:9.", completion = "The destruction of the machines XT:4 and XT:9 have soothed many of the spirits of Stonetalon, {name}.  With their loss, let us hope the Venture Company will remove itself from these mountains.\n\nFor if they do not, then I fear the atrocities this place has suffered will pale to what lies ahead.", objectives = "Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1069] = { id = 1069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepmoss Spider Eggs", description = "Spider egg omelettes are a new fad in Booty Bay!  The problem is... Booty Bay's got no eggs.\n\nI smell an opportunity!\n\nIn Windshear Crag and Sishir Canyon, in the Stonetalon Mountains to the northwest, lives the deepmoss spider.  Bring me its eggs and I'll pay a bundle!\n\nIn Windshear Crag, the eggs will be clustered under what trees remain.\n\nIn Sishir Canyon... well, if you have a weak stomach then maybe you should just collect the eggs at Windshear Crag...", progress = "Did you get the eggs, {name}?  I already made a shipping deal with Wharfmaster Dizzywig!", completion = "You got them!  Thank you!\n\nI'll have these sent to Dizzywig and get them shipped to Booty Bay.  I can already taste the profits!\n\nHere is your cut, {name}.  I couldn't have made this deal without you.", objectives = "Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1070] = { id = 1070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Guard in Stonetalon", description = "Hello, {name}.\n\nYou seem to be full of wanderlust by the looks of you. Have you been to the Stonetalon Mountains? It is a land plagued by the Venture Co. and other enemies of the night elves.\n\nRecently, Sentinel Wolfrunner sent my friend Kaela Shadowspear there to investigate what's happening to the land, but I have yet to hear word back from her. I'm even more concerned because the Alliance sent a gnome mage along with her... a sign of trouble for sure.\n\nWould you find her and report back to me?", sourceObjective = "Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains.", completion = "Ah, you've come from Ashenvale at the behest of Tara--how I miss her, my homeland and friends. She must be doing well with the Sentinels to be sequestering adventurers for other tasks. I'm proud of her.\n\nIt is a pleasure to meet you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1071] = { id = 1071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gnome's Respite", description = "You see, {name}, I'm a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and it's my goal... nay, my DUTY! to show the night elves that a blend of magic, mixtures, and mechanisms can help save their forests.\n\nBut it's a hard fought war, and the goblins reproduce like rabbits it seems. I haven't even had time to build my newest inventions!\n\nI need some time to plan and organize. But to do that, I need your help keeping the goblins at bay in Windshear Crag to the east...", completion = "Thanks so much for your help, {name}. You're actually back just in time.\n\nI think I've got a perfect plan... explosives. No, that's not the plan, but it's part of the plan.\n\nSee, I've been using high explosives--don't worry, they're not as dangerous as everyone thinks--to scare the goblins back a bit. I can herd 'em pretty good with a few key detonations along the mountains' edges, but I've been low on supplies now for a few days...", objectives = "Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1072] = { id = 1072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Colleague", description = "The device I'm thinking about is my most advanced version to date. But we'll need a special potion if it's to work. I'm thinking we might as well get the good stuff since this mission could be your last.\n\nAnd for that, we're going to need some potent explosives: Nitromirglyceronium.\n\nThe only person who can make NG-5 is an old friend of mine: Lomac Gearstrip. Look for him in Tinker Town.\n\nYou talk him into making us some NG-5, I'll get to work on placement for my devices.", sourceObjective = "Speak to Lomac Gearstrip in Ironforge.", completion = "Ahhh.... Gaxim sent you, huh? How do I know you're not lying to me?! Hmm? Hmm...?", sourceObjectiveStatus = "unverified-source-field" }
quests[1073] = { id = 1073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ineptitude + Chemicals = Fun", description = "Hahaha... you need Nitromirglyceronium to stop goblins from destroying a forest?!\n\nI don't care if you know Gaxim or not... I'll give you the stuff just to see you or them explode into itty bitty pieces.\n\nThere's a problem though: I'm all out.\n\nBut I'll tell you what, you bring me the correct potions, and I'll make some up for you right away.\n\nThe least you can do is prove you've got some skill as an alchemist before I just give you a sample of my greatest creation.", progress = "I can't make any Nitromirglyceronium if I don't have the potions... they're vital to its creation.", completion = "This'll do nicely.\n\nIf I didn't know better, stranger, I'd say you knew somethin' about alchemy. Good, good... the world's not all about swords and sorcery, you know?", objectives = "Bring 4 Minor Mana Potions and 2 Elixirs of Minor Fortitude to Lomac Gearstrip in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1074] = { id = 1074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ineptitude + Chemicals = Fun", description = "Here you go, stranger. Take heed with it though... it's volatile stuff.\n\nIf you're really a friend of Gaxim's, then tell him I say hello. If you're not, then have fun blowin' yerself up.", progress = "Ah, goodie goodie, you're back.", completion = "Your task has been done flawlessly, {name}.\n\nNG-5 is the unequivocal component in the recipe to ignite the wagons of dynamite.\n\nWhat? Yes, dynamite... wagons of it. It's the perfect distraction, I tell you... just wait and see.", objectives = "Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1075] = { id = 1075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scroll from Mauren", description = "Okay, now for the remote detonation part of my plan... oh, I haven't explained that yet, have I?\n\nOkay, so the short of it is this: with a little magic, I can make it so the explosives go off while you're not around. I'm putting together a device that'll allow you to push just one button and have the NG-5 explode when you're ready.\n\nBut I need a spell from a friend in Stormwind--Collin Mauren is his name. You can find him in the mage quarter there. He's human, so he shouldn't be hard to miss.", sourceObjective = "Find Collin Mauren in Stormwind.", completion = "Now, this spell you need; one that will allow you detonate explosives from a distance... hmmm.", sourceObjectiveStatus = "unverified-source-field" }
quests[1076] = { id = 1076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devils in Westfall", description = "Ah, I think I have it. A messaging spell... I believe that's the effect he's looking for.\n\nI'll have to create a scroll with the spell impressed upon it. To do that I'll need debris from a dust devil.\n\nWhile I gather the rest of the components, why don't you head to Westfall and find one of the foul creatures? They are dangerous, but I'm sure it's nothing you can't handle if you're willing to subject yourself to one of Gaxim's experiments.\n\nI'll be here when you return.", progress = "Hello, {name}. Have you found the component I need?", completion = "Allow me just a few moments and I shall have your scroll ready for you.", objectives = "Bring Dust Devil Debris to Collin Mauren in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1077] = { id = 1077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Delivery for Gaxim", description = "Here you are, {name}. This should do nicely.\n\nPlease give my regards to Gaxim when next you see him. I look forward to hearing about this adventure when it sees its completion.\n\nFare well.", progress = "Haha! you're back! Do you have it? Do you have the spell?", completion = "This is perfect, {name}! Well done.\n\nThis spell, mixed with the NG-5, shall make the perfect remote explosive.\n\nWe'll be able to create the perfect distraction for you so you can sneak in and steal the Venture Co.'s letters and engineering plans.\n\nThat will surely slow down their deforestation acts.", objectives = "Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1078] = { id = 1078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retrieval for Mauren", description = "Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co.\n\nWithin the Charred Vale, deep in Stonetalon, there used to be a species of basilisks whose scales, when ground to dust, made a wonderful reagent for some spells I've created.\n\nIf those basilisks still live, I would love to have a few of their scales.\n\nTake your time, it is no rush, but I can pay well.", progress = "Hello again, {name}.\n\nHave you already returned from the Vale in Stonetalon with those scales?", completion = "This is perfect, {name}. Thank you greatly.\n\nPerhaps one day in the future I'll be able to help you as you have helped me.", objectives = "Bring 8 Crystalized Scales to Collin Mauren in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1079] = { id = 1079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Covert Ops - Alpha", description = "This is it, {name}. Pay close attention. The devices are done, and ready to be used.\n\nTake these pages--they'll explain more about the detonators and explosives, and where you should place them.\n\nRemember, the success of your mission doesn't depend on how much destruction you cause. Plan Alpha's success depends on you bringing back the Venture Co.'s engineering plans from inside the lumber mill south of Cragpool Lake.", progress = "Did you get the plans, {name}?", completion = "Truly amazing! This is a huge blow to the Venture Co.\n\nWe'll be able to find weaknesses in their machines and also incorporate their designs into our own creations. This is a wonderful day, indeed.", objectives = "Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1080] = { id = 1080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Covert Ops - Beta", description = "Plan Beta's just like Plan Alpha, {name}.\n\nWe cause a distraction and then steal their precious letters.\n\nThe key is to get their letters... remember that.\n\nThe pages I gave you already will tell you where to plant the explosives. Just get back here alive and with those letters....", progress = "How'd it go, {name}?", completion = "Incredible, {name}! Kaela and the Sentinels will be so happy. With your skill and my creations, we're unstoppable.", objectives = "Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1081] = { id = 1081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reception from Tyrande", description = "{name}, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission.\n\nIt may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains.\n\nIf you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus.", sourceObjective = "Find Tyrande Whisperwind in Darnassus.", completion = "Hello, {name}. I have indeed heard your name before, and although you are still full of youth, I am pleased to see the path you have set for yourself.\n\nYou would do me a great honor if you would accept this as a gift of appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[1082] = { id = 1082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Update for Sentinel Thenysil", description = "{name}, you have done a great deed by lending a hand here.\n\nThe Sentinels of Ashenvale will reward you well if you informed them that Gaxim and I are alive. Tell them we are well on our way to stopping the Venture Co. and healing the lands.\n\nFind Tara Thenysil in Astranaar; she will be pleased to see you've returned with good news.", sourceObjective = "Return to Sentinel Thenysil in Ashenvale.", completion = "Thank you, {name}. You have done a service to the Sentinels.\n\nI'm glad to see Kaela... and even Gaxim, are doing well.\n\nYou've earned our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[1083] = { id = 1083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Spirits", description = "I'm unsure what the Venture Co. did to the Vale, but it's obvious they were overpowered by the creatures there.\n\nThey set the forest aflame, and used their inventions of destruction to decimate as much of the Vale as possible.\n\nBut in their ignorance they also released something else: burning spirits, elementals of flame, stone and rage.\n\nThe land has no chance to see Elune's smile while these creatures roam free.\n\nBring me their smoldering embers to show you've reduced their numbers.", progress = "The first time I saw the Charred Vale I almost wept, {name}.", completion = "The remains of our enemy... your strength serves us well, {name}. Thank you.", objectives = "Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1084] = { id = 1084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wounded Ancients", description = "It seems obvious to me that the protectors of the Vale--the treants--had something to do with the Venture Co. being driven back. Unfortunately, even those once great guardians have now become corrupt.\n\nGaxim thinks their corruption is somehow linked to the weapons the goblins used during their retreat.\n\nI told him I'd collect a sample from a wounded treant and allow him to study it in order to figure out if that's true.\n\nBring me some of the shrapnel so the gnome can tell me more...", progress = "I have a feeling Gaxim will find a use for the shrapnel regardless of how the Venture Co. has used it in the past.", completion = "Thank you, {name}.\n\nThis should be more than sufficient for Gaxim to figure out how the treants were corrupted. I shall give this to him right away.", objectives = "Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1085] = { id = 1085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Guard in Stonetalon", description = "The situation here in Stonetalon is obviously grave for a night elf and gnome to be working together.\n\nThe Venture Co. has devastated these lands and I've spent most of my time putting an end to the destruction.\n\nDo not judge Gaxim prematurely; he understands the need for us to work together.\n\nIf you wish to aid us, then start by speaking to Gaxim.\n\nI'm sorry I cannot send you back to Tara with good news yet. Perhaps soon.", sourceObjective = "Speak to Gaxim in Stonetalon Mountains.", completion = "Treacherous... treacherous and dangerous, that's what this land is.\n\nBut I'm here to show the night elves that it's a little safer with the help of good ole engineering and a dash of magic.\n\nSee, swearing off magic completely won't help the night elves--they need it. The world needs it. And with engineering and alchemy to boot, you can't go wrong. The possibilities are endless.", sourceObjectiveStatus = "unverified-source-field" }
quests[1086] = { id = 1086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flying Machine Airport", description = "The toxin is ready.  All that remains is its delivery.  You, {name}, must make that delivery.\n\nThe Venture Company must have a means of sending messages and light cargo between its headquarters and its operations in Stonetalon.  It is likely a small sky port -- not big enough for a zeppelin, but perhaps for a flying machine.  You must search the areas in Stonetalon under control of the Venture Company and find this sky port, if it exists.  If you find it, then place the toxin there.\n\nPlace it, and run.", completion = "You found the port?  Well done, {name}!  I am sure the goblins were quite surprised from your delivery!  Let us hope that toxin finds its way to their headquarters.\n\nYou have served your people well, and I advise you to ignore any guilt you might harbor for poisoning the Venture Company.  They are deserving of far worse.\n\nAnd if there is one mote of wisdom the Forsaken might teach its allies, it is this:\n\nDo not shy from dark paths... if those paths lead to victory.", objectives = "Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1087] = { id = 1087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarius' Legacy", description = "You cannot imagine the hatred I possess for this wretched land. The ilk of Cenarius and the kaldorei druids at the peak employ their pathetic powers to stifle the flow of magic, even so far south of their pathetic holdings... their beloved forests.\n\nWould that I could return to Jaedenar and exult in the flow of magic, but my master will not allow me to return until my work is done.\n\nI have no doubt you love the night elves and their allies as little as I. Aid me, and both our ends might be satisfied.", completion = "Already I can feel it... yes... power so sweet... the rushing flood. The kaldorei are foolish to spurn the gifts of this world, to reject the coursing of magic as it flows singing through your veins.\n\nWhat a pale mockery life is without its burning embrace!", objectives = "Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1088] = { id = 1088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordanus", description = "They thought that they could halt the flow of magic. They were mistaken. They thought that they could hide Ordanus, but I will have his head!\n\nMagic grants me true sight. Yes... there he is. A crossroads... At the top of a great tree in Ashenvale Forest. A name... Raynewood. One of the eldest sons of the forest god. They spirited him away from the peak before I could find him, but his time runs short.\n\nBring it to me and I will share with you a mighty gift.", progress = "When my master bade me to the peak of Stonetalon, I expected that all I would need was to lay waste to the night elves that crawled the sacred ruins of our ancient temple of Azshara, their touch despoiling its sanctity... but Ordanus had slipped my grasp.", completion = "I knew Ordanus once, long ago. He had the arrogance of his kind, holding himself above even the Highborne.\n\nHis head does not rise so high now, does it, {name}?\n\nI promised you a reward, and you shall have it. Attend to me.", objectives = "Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1089] = { id = 1089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Den", description = "The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items.\n\nThey devised a complex scheme to keep them from falling into the wrong hands.\n\nLuckily, I managed to... extract some details from one of them.\n\nHidden in a small lantern at the entrance of the Den, you will find the Gatekeeper's Key--with it you will be able to open caches around the Den. The items from these caches will allow you to open their hoard, located in one of the central areas.", progress = "Three keyholes are carved into the stone.", completion = "As the three keys are slid into their matching openings, in the middle of the glowing light a number of items appear.", objectives = "Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1090] = { id = 1090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo's Orders", description = "You know, I was once the second most important person here at this site. That all changed when Gerenzo took over. Fired my boss, Ziz Fizziks, and sent me down to work in the mines. Ziz told me to stay here and gather information, though. His new boss will pay us well if we can find out what Gerenzo's plans are.\n\nAnyways, what I do know is that Gerenzo has ordered large amounts of this gold-green ore to be mined. I can get you a sample to bring to Ziz, but you'll have to watch for patrols while I get it.", completion = "Thanks, {name}. It was looking a little dicey there for a second and we've probably drawn far too much attention to ourselves.\n\nThe important part is that we have the ore sample, though, and we should get it to Ziz as soon as possible.", objectives = "Get the mysterious ore from Piznik after he finishes mining it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1091] = { id = 1091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaela's Update", description = "{name}, take these letters to Kaela. I'm sure she'll want to know about this. Or at least the Sentinels will.\n\nMake sure you tell her how successful we were and how we couldn't have done it without a little bit of magic.", progress = "Yes, {name}? What can I do for you?", completion = "This is interesting indeed.\n\nYou and Gaxim have done very well, {name}. Thank you.", objectives = "Bring the Venture Co. Letters to Kaela Shadowspear in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1092] = { id = 1092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo's Orders", description = "I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again.\n\nI'll sneak out and meet with Ziz. Hopefully, he'll be able to find me a new job!\n\nI'll try and clean up this mess a little, but you should take the ore sample to Ziz right away. He told me that he'd set up camp somewhere on the western side of Windshear Crag. Good luck.", progress = "Something I can help you with?", completion = "Ahhh, I knew that I did the right thing by telling Piznik to stay behind. I'm sure the engineers in Undermine will be most interested to look at this...\n\nOf course I'll want to keep a little piece for myself, but what they don't know won't hurt them, yes?", objectives = "Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1093] = { id = 1093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Reaper 6000", description = "Terrible what the Venture Company has done here, eh? What were they thinking? Goblin company hiring a gnome!\n\nLucky for me, Sputtervalve knows a genius when he sees one. Hired me just after I'd been kicked out!\n\nTells me they built some enormous woodcutting machine, and Sput' wants me to steal the plans for him. Unfortunately, Gerenzo--bloody gnome--wants me dead on sight... maybe you could steal the plans for me? You should be able to find them on one of their operators.", progress = "Did you find those plans? I'm eager to impress the new boss. Hopefully, once he's convinced of my loyalty--well, as much as he can be convinced... goblin's honor, you know?--he'll feel comfortable making use of my rather impressive genius.", completion = "Hey, is that what I think it is? Great!\n\nNow, let's see. Ugh... how am I supposed to understand this stuff... can't figure out the way gnomes think. Lemme tell you, I'm surprised they could build the wheel, let alone those flying machines they like so much.", objectives = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1094] = { id = 1094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Instructions", description = "This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.\n\nSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow.", progress = "Hello there! How can I help you?", completion = "Fizziks, eh? Can't say I trust him, but this information seems good enough. What I wouldn't give to have the Venture Company out of my hair.\n\nThey do come up with some good machines though... I can't deny that we've benefited from using some of the improvements they've devised.", objectives = "Deliver the Sealed Envelope to Sputtervalve at Ratchet in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1095] = { id = 1095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Instructions", description = "The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.\n\nRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.\n\nWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him.", sourceObjective = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.", completion = "Eliminate Gerenzo? Now there is a prospect that I have no objections to.\n\nGnomes are bad enough as it is, but what I learned about Gerenzo only makes it worse. Apparently, he was one of the head engineers in Gnomeregan, where he was working on their secret project--we could never infiltrate Dun Morogh well enough to find out specific details. It was a failure. Our reports say that whatever it was literally exploded in their faces.", sourceObjectiveStatus = "unverified-source-field" }
quests[1096] = { id = 1096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo Wrenchwhistle", description = "I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones.\n\nNortheast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it.\n\nIf you kill him for me, I'll make it worth your while!", progress = "Sputtervalve will want some sort of proof that Gerenzo's dead. I think his mechanical arm will probably do.", completion = "Look at that thing... it'd take a gnome to come up with something like that. I can't understand why you'd cut off an arm, and replace it with that, when you could just keep both arms and add a third!\n\nGnomes, I tell you...\n\nAt least Gerenzo's out of commission. Hopefully that'll be enough proof, and Sputtervalve will assign me to one of the Tinkers' Union workshops in Gadgetzan or maybe even Undermine.", objectives = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1097] = { id = 1097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elmore's Task", description = "There's a dwarven weaponsmith in Stormwind, Grimand Elmore, who sent word that he needs help with a delivery.  I believe he wants a package sent to his homeland in the north.\n\nYou have a sturdy pair on you!  So if you're interested in some legwork then speak with Grimand.  We could use you down here, but we must also keep our ties strong with the dwarves.\n\nYou can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.", completion = "You're here to help with my delivery?  Very good!", objectives = "Speak with Grimand Elmore in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1098] = { id = 1098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathstalkers in Shadowfang", description = "In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence.  It has been many days and they have not returned, but we must receive their report if we're to have any hope of a successful attack!\n\nSo here is your task, {name}.  Go to Shadowfang Keep to the south and find the Deathstalkers Adamant and Vincent.  Find them, and if they require aid then give it.\n\nThis mission is as dangerous as is it critical, {name}.  Do not fail.", completion = "Vincent's body lies broken, and still.\n\nAlthough Deathstalker Adamant will send his report to Hadrec... whatever additional details Vincent gained must remain with him.\n\nBut clutched in his hand is a small trinket...", objectives = "Find the Deathstalker Adamant and Deathstalker Vincent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1099] = { id = 1099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblins Win!" }
quests[1100] = { id = 1100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lonebrow's Journal", description = "You slowly open the weathered journal of Henrig Lonebrow....", progress = "From your look of concern, I can tell that something is amiss....", completion = "You say you found this journal on a deceased dwarf? Give me but a moment to peruse the pages...", objectives = "Read Henrig Lonebrow's Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1101] = { id = 1101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crone of the Kraul", description = "Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was.\n\nWe must not let their valiance go for naught. This crone... Charlga Razorflank ... must be stopped.\n\nSurely, infiltrating the Kraul will be perilous. There isn't time to send word to Darnassus. {name}, assemble a party to slay the crone.\n\nBring me Razorflank's Medallion as proof of demise.", progress = "So long as Charlga Razorflank is mustering a force in Razorfen Kraul, these lands are in great danger.", completion = "The crone has been laid to rest. This is fantastic news, {name}.\n\nIn these times of peril, it is refreshing to see one as brave as yourself.\n\nWith Razorflank's minions taken care of, our studies in the area can continue. Perhaps now we can gain further knowledge of exactly what happened to corrupt the resting place of Agamaggan.\n\nHowever, I fear the answer to that question lies in treachery as well...", objectives = "Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1102] = { id = 1102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Vengeful Fate", description = "Cairne is a noble leader for uniting our people here on Thunder Bluff.\n\nBut I cannot forgive those who drove us from our ancestral lands as easily as some. My people inhabited the southern Barrens for decades. The land was holy to us. But we were driven off by numerous foes.\n\nA vengeful fate awaits the crone, Charlga Razorflank, who musters a foul army from within Razorfen Kraul.\n\nBring me Razorflank's heart and I can die in peace, {name}.", progress = "Once I know the foul beasts of Razorfen Kraul have been driven from their foul lair, I will be able to rest in peace, knowing that revenge has been served.\n\nHave you driven the quilboar from the Kraul? Do you bring to me good news in the form of Razorflank's heart?", completion = "I see the nasty tribe of Razorfen Kraul now knows the pain of my people. Serves the foul beasts right.\n\nTo drive one from a holy land is a sin worthy of the most severe revenge.\n\nThank you, {name}, for aiding me in my plight.", objectives = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1103] = { id = 1103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Greetin's, <brotha/sista>! Have you too come to purify the waters here and prove your understandin' to Islen?\n\nI've just defeated the corrupt water spirit meself, and I'm just 'bout to put da bracers and remaining drops o' water on the brazier.\n\nWhat's dat? Ahhh. Tiev understan' all too well when somethin' goes wrong. Well, Tiev can help you plenty if you be needin' to see the pure water spirit again.\n\nBring me a water sapta from Islen as proof that you be ready, an' I'll wait to turn in me parts.", objectives = "Bring a Water Sapta to Tiev Mordune in Silverpine Forest if you failed to speak to the Minor Manifestation of Water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1104] = { id = 1104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salt Flat Venom", description = "I have so many designs for our rocket car!  So many!  And I must try them all!!\n\nI'm working on a new type of fuel.  One that burns really really really hot!!  I haven't gotten the mixture perfect, but I think I know what I need...\n\nThe scorpids who wander the Shimmering Flats have a venom with lots and lots of salt in it.  It's very unique!  And it's just what I need!\n\nBring me venom and trust me -- our car will fly!!", progress = "Hi hi hi!  Did you get that venom??", completion = "All right!  This venom is going to work great!  Thanks, {name}!\n\nNow I just need to boil it down, apply skipper-otomer, add a nega-catalyst, and... Drat!  Where are my notes!?", objectives = "Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1105] = { id = 1105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hardened Shells", description = "My brother is working on a new fuel for his rocket car.  He's brilliant, he really is.  So brilliant that... I think that new fuel he's designing is strong enough to eat right through the car's chassis!\n\nI want to reinforce its fuel tanks before that happens.\n\nThe tortoises out on the flats have very hard shells.  I want to use them to create new tanks for our rocket car.  Tanks that can hold my brother's new fuel.\n\nYou look responsible enough.  Will you get me those shells?", progress = "My brother is making progress with his new fuel design, and that has me worried.  I need to start work on a tortoise shell fuel tank as soon as possible!\n\n{name}, do you have those shells yet?", completion = "You got them!  Thanks, {name}!\n\nWow, these shells are harder than I thought!  Heh, when I work with them I'll probably bend a whole box full of tools!", objectives = "Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1106] = { id = 1106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Martek the Exiled", description = "I'm developing a new engine that'll make the car go so fast!  Fast enough to fly, I know it!  I just need to make pistons that can handle very very heavy stress.  All my trials have failed because I can't make pistons hard enough!\n\nBut there is someone who might know how.\n\nHis name is Martek the Exiled.  He is a great smith and knows more about metal than anyone.  Take him this letter, I know he can help!\n\nBut he's far far away -- in Azeroth, in the Badlands, in a camp, with a goblin!\n\nFind him!", progress = "Well, you found me.  Good for you.\n\nAre you here about that axe I made for Gath'Ilzogg?  Or are you here to reclaim Duchess Pamay's honor?\n\nActually, I don't care which it is.  If you're here to fight, then let's get it over with...", completion = "Fizzle sent you?  Well that changes things!  Of course I'll help you.  Fizzle and his brother are two of the few people who don't want me dead!\n\nSo Fizzle wants to make pistons, eh?  Pistons strong enough to take whatever stresses he has planned, and if I know Fizzle, then this new car of his is a volcano on wheels!", objectives = "Bring Fizzle's Letter to Martek the Exiled in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1107] = { id = 1107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrusted Tail Fins", description = "Our rocket car is the fastest thing on the flats!  So fast that ... I'm afraid friction is going to tear it apart!\n\nTo prevent that I need to create a composite to coat the car's moving parts.  It must be hard but not brittle, and must be resistant to salt corrosion, or time spent on the Shimmering Flats will eat it away.\n\nHave you heard of the Vile Reef, {name}?  It's off the coast of Stranglethorn Vale.  Saltscale murlocs live there, and their tail fins are a crucial ingredient of my composite.", progress = "Do you have the tail fins?  If I can't protect our car from its own speed, then it won't last long in these races.", completion = "Thank you, {name}!  After I grind these down and fuse them with a few other ingredients, the composite will be ready.  And after that, the car will be safe from its own speed.\n\nSafe, as long as it doesn't hit anything...", objectives = "Bring 10 Encrusted Tail Fins to Wizzle Brassbolts in the Shimmering Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1108] = { id = 1108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Indurium", description = "I'm not out here just to stay away from people.  There is a wealth of metal in the Badlands, {name}, if you have the guts to get it.\n\nThe metal's called indurium and as luck would have it, it is rumored to possess high resistance to heat and stress.  It might work for Fizzle's car.\n\nBut let's make sure.  Get me samples of indurium and I'll test its properties.\n\nTrue indurium ore lies deep in Uldaman, but the Stonevault troggs of the Badlands sometimes have flakes of it on them.  Bring me those flakes.", progress = "Did you find any indurium flakes, {name}.  I have my forge heated up and ready to test them.", completion = "Ah yes, these will do fine.  Now let's put them in some heat and see how they fare...", objectives = "Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1109] = { id = 1109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going, Going, Guano!", description = "As you can see, {name}, we're up to some very.... interesting experiments at the Royal Apothecary Society.\n\nAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!\n\nYou look well traveled for a {class}. Perhaps you can aid me.\n\nI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...", progress = "Ah, I see you have returned. Were you able to procure any Kraul Guano?", completion = "Splendid! This is just the start we needed, {name}.", objectives = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1110] = { id = 1110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Car Parts", description = "Heh heh, with all the races they're running here, it's no surprise that a few mishaps happen along the way.  If you look around the Shimmering Flats then you'll see evidence of past crashes -- scraps of rocket car parts are littered everywhere!\n\nAnd those parts are worth money to the gnomes and goblins.  They're always looking for more contraptions to slap onto their cars.\n\nSo go out and get me parts.  Bring me a heap and I'll pay you well.", progress = "{name}, have you been out into the Flats?  Did you bring back that load of parts I wanted?", completion = "Whoa, look at all that!  There's some good stuff in that heap of junk.  I'm sure I can pawn it off for a hefty sum.\n\nAnd... is that an ear I see squashed between those two sheets of metal??  Ouch!  Heh, I sure wouldn't want to be that pilot!\n\nThanks, {name}.  Here's your pay.  And here's some advice, free of charge...\n\nIf you look hard enough, you can always find profit in someone else's tragedy.", objectives = "Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats.Heh heh, with all the races they're running here, it's no surprise that a few mishaps happen along the way. If you look around the Shimmering Flats then you'll see evidence of past crashes -- scraps of rocket car parts are littered everywhere!\n\nAnd those parts are worth money to the gnomes and goblins. They're always looking for more contraptions to slap onto their cars.\n\nSo go out and get me parts. Bring me a heap and I'll pay you well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1111] = { id = 1111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wharfmaster Dizzywig", description = "I make it my job to get people what they need, and the gnomes over there need a parts order filled.  Their parts were shipped to Ratchet a week ago, but I haven't been able to make the trip.\n\nSo, are you ready for some legwork?  Go to Ratchet and give this parts order to Wharfmaster Dizzywig -- he'll probably be at the docks.\n\nDo this for me, and I'll have more jobs for you.\n\nJobs, my friend, with serious profit potential...", progress = "Speak up!  Tell me, are you dropping off or picking up?", completion = "Oh yes.  Parts for Kravel.  I'm glad you're here.  These things have been sitting out here for days, and I was afraid they'd rust!", objectives = "Bring Kravel's Parts Order to Wharfmaster Dizzywig at Ratchet in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1112] = { id = 1112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts for Kravel", description = "Here's Kravel's package, {name}.  And when you deliver it, tell him... if he wants more special orders, then he'll have to pay his tab!", progress = "Did you make it to Ratchet and get those parts?", completion = "Great, you got them!  Now we need to get them to the gnomes.  But first...\n\nLet's take out one small item...", objectives = "Bring Kravel's Parts to Kravel Koalbeard on the Shimmering Flats in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1113] = { id = 1113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hearts of Zeal", description = "Why do I need a rare type of guano, you might ask. Well, for this experiment I want to see what effect two diametrically opposed chemical substances can have on each other, especially when both are combined with an ever-toxic agent to ensure the most... ghastly results.\n\nIn the northeastern peaks of Tirisfal Glades lies the Scarlet Monastery. There the crazed disciples of the Scarlet Crusade congregate, both inside and outside the halls. Which you slay matters not, any of them may have the heart I need.", progress = "Have you returned from the Scarlet Monastery? I'll need many hearts for this delightful experiment!\n\nNo doubt, Varimathras and the Dark Lady will be pleased to be rid of the Scarlet Scum as well...", completion = "My what an abundance of gore you have brought me, {name}! Your efforts have been most excellent!", objectives = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1114] = { id = 1114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to the Gnomes", description = "Now that I have what I need, give these parts to Fizzle Brassbolts.  He's been waiting a long time for them -- I'm sure he won't miss the little piece I removed from his order...\n\nAnd I wouldn't bother mentioning it to him.  It was small and worthless.\n\nTrust me.", progress = "You have something for me?  That's great!  let's see it!", completion = "There they are!  My hydro ratchets and repeater bolts!  These will do just fine.  Thank you!", objectives = "Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1115] = { id = 1115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rumormonger", description = "Now that we've done a service for the gnomes, it's time to do the goblins a favor!  \n\nI hear that the goblin racer pilot, Nazz Steamboil, didn't always use that name.  I wonder why he changed it.  I wonder if it's a secret, and... I wonder if he values that secret.\n\nIf anyone knows the truth, then it's Krazek of Booty Bay, on the southern tip of Stranglethorn.  Speak with Krazek and ask him about our goblin pilot.\n\nIf you can get useful information from him, then we might just turn a profit from it.", completion = "You want to know about Nazz Steamboil?  He's a racer pilot out in the Shimmering Flats, isn't he?\n\nYeah, I might be able to find something out about him... but it won't be easy.  Or fast.\n\nOr cheap.", objectives = "Talk to Krazek at Booty Bay in Stranglethorn Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1116] = { id = 1116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream Dust in the Swamp", description = "Getting the information on Nazz is quite a favor, {name}.  Yes, quite a favor.  But you've come all the way from the Shimmering Flats to get it... are you willing to travel some more?\n\nWhile I contact my sources, why don't you gather something for me, eh?\n\nHm... what will it be?  How about dream dust, from the dragon whelps of the Swamp of Sorrows.  Yes, I'd love some dream dust for my snuff pouch!\n\nGet it for me, {name}, and I'll give you the information you seek.", progress = "Back so soon?  Do you have my dream dust?", completion = "Well, look at that.  You found the dream dust!\n\nAnd how did you like the swamp, {name}?  It's not easy to get a hot meal there, is it?", objectives = "Bring 10 Specks of Dream Dust to Krazek in Booty Bay. Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1117] = { id = 1117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumors for Kravel", description = "I had to use some of my favors, and gave away a rare bottle of elven wine, and did some heavy deducing myself!  But I found the information you seek.\n\nHere, I wrote a letter with some very interesting bits on our friend, Nazz Steamboil.  Do with it what you will -- it's too dangerous for me to use.\n\nJust don't tell anyone where you got it!", progress = "Did you get anything on Nazz Steamboil?  Anything he might want to keep a secret??", completion = "Well well!  This is interesting... very interesting.  Heh, perhaps I should bow to the goblin pilot the next time I see him.\n\nThis is worth plenty, {name}.  I'm sure Nazz will pay a small fortune to keep his secret... a secret.", objectives = "Bring the Goblin Rumors to Kravel Koalbeard on the Shimmering Flats in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1118] = { id = 1118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Booty Bay", description = "{name}, you're a {class} I can trust, both to get the job done and to keep your mouth shut while doing it.\n\nI've been brewing up a new scheme.  It's risky, but if it works then we could both make a bundle!  And I think you're just the person to see it through.\n\nTo start, you must go back to Booty Bay.  I apologize, good {name}.  I know my last task took you there.  But this time, speak with Crank Fizzlebub.\n\nGive him this letter.  And if he requires aid, do your best to help him.  It will be worth the effort.", progress = "Hello hello.  And what brings a noble {race} such as you down to Booty Bay?", completion = "I see.  Kravel has a big scheme planned.  He has a sinister mind -- I like that about him.\n\nSo you'll need something to addle wits, eh?  Something powerful...\n\nI wonder if the mixture Zanzil feeds his zombies could be used...", objectives = "Bring Kravel's Scheme to Crank Fizzlebub at Booty Bay in Stranglethorn Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1119] = { id = 1119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzil's Mixture and a Fool's Stout", description = "I figured out how to use Zanzil's mixture with stout to make a powerful libation.  A Fool's Stout.  I think it'll be just what Kravel needs, but try it out and let me know how it works.\n\nAnd {name}, don't keep this stuff too long without using it.  Zanzil's mixture has a weird effect on the stout's yeast, kicking it into high gear.  So it won't stay fresh forever.", progress = "Hello, {name}.  Was Fizzlebub able to help us?", completion = "Wonderful!  Fizzlebub came through!  I'll remember that next time I see him.\n\nAnd thank you, {name}.  You're doing a great job, and we both stand to make a lot of money from this...", objectives = "Bring the Fool's Stout back to Kravel on the Shimmering Flats in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1120] = { id = 1120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Gnomes Drunk", description = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the gnomes, then here -- take the stout and give it to the gnome pit boss.\n\nAnd don't wait too long.  This stout will go bad eventually.", progress = "Hi!  You have something for me?", completion = "Stout?  How considerate!  Thank you!\n\nWe shouldn't be drinking with the race coming up, but... maybe my boys could do with just a little.  Besides, it can't be that strong, can it?", objectives = "Bring the Fool's Stout to the Gnome Pit Boss at Mirage Raceway in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1121] = { id = 1121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Goblins Drunk", description = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the goblins, then here -- take the stout and give it to the goblin pit boss.\n\nAnd don't wait too long.  This stout will go bad eventually.", progress = "What are you looking at?", completion = "What do we have here?  Booze, eh?\n\nWell, I don't mind if we have just a little...", objectives = "Bring the Fool's Stout to the Goblin Pit Boss at Mirage Raceway in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1122] = { id = 1122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report Back to Fizzlebub", description = "That Fool's Stout worked great!  I placed a bet on the next race, and... let's hope the crew you got drunk did a number on their car!\n\nThere's only one more task for you -- take this note back to Crank Fizzlebub in Booty Bay.  He'll want to know of the successful test.\n\nAnd hopefully we can get more of that Fool's Stout for future races!", progress = "Hello {name}.  How'd that stout work out?  It's strong stuff, isn't it?", completion = "It says here that the fool's stout was a success.  That's good news!\n\nIf you ever want more of the stuff, then let me know and I'll have you gather more of Zanzil's Mixture.", objectives = "Bring the Fool's Stout report to Crank Fizzlebub at Booty Bay in Stranglethorn Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1123] = { id = 1123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabine Saturna", description = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris and Un'Goro.  He is located in Nighthaven, the main village of Moonglade.\n\nI want to impart on you the importance of your presence.  There are growing tensions between the night elves of Darnassus and the Cenarion Circle in Moonglade.  Look beyond racial boundaries and tap into the wisdom of your ancestors in dealings with the Circle there, {name}.  Good luck.", completion = "I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.\n\nI appreciate your interest and eagerness to assist the Cenarion Circle.  The tauren have shown an incredible propensity to the tenets of Cenarius, and by their proxy the Horde is welcomed within the safety of this glade.  The preservation of Azeroth is a common goal we both share.\n\nYou are among friends here, {name}.", objectives = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade. Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1124] = { id = 1124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasteland", description = "West of Un'Goro Crater, via the northwestern ridge, is a harsh wasteland - Silithus.  Few know that an ancient war was waged there between the night elves and a malign, alien power.  The evil was sealed, but now we suspect that forces work to stir this... unspeakable horror.\n\nSeek out Layo Starstrike, one of our agents in Silithus; look for him at Valor's Rest, the final resting spot for the fallen of the wastes.  Give him this letter, and he will give you his trust accordingly.", progress = "This is a dangerous land to be so casual, {class}.  What brings you to the wastes of Silithus?", completion = "Rabine sent you, did he?  Well, consider yourself welcomed here... as much as this desolate and forsaken land can welcome someone.\n\nI wasn't alive during the time of the great tribulations that took place here, but there are parts of this desert that might as well be eerie pictures of that forgotten past.  With your help, the Cenarion Circle might be able to bring finality to a threat that was supposed to have died generations ago.", objectives = "Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1125] = { id = 1125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirits of Southwind", description = "To our southwest lies a tragic site - the ruins of Southwind Village.  This is where our work should begin, {name}.\n\nFrom what we've learned, this village was once a night elf base of operations for Silithus.  It's long since overrun by the silithid hives that infest the wastes.  I can only imagine the horror of the village's initial sundering...\n\nThe tortured spirits of fallen druids and sentinels wander the ruins aimlessly.  Explore this locale, freeing the souls of these wretched beings as needed.", completion = "I had thought that maybe the huge swirling hive near the ruins of the village had played a part in its demise.  It would seem that your work has proven this to be correct; the proximity of the hive poses a threat to any future work we may do here.\n\nI thank you for your benevolence in freeing the souls of the fallen; such work is never easy, I know.  When you're ready, however, I'd like to ask for your assistance once more...", objectives = "Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village, and then return to Layo Starstrike at the Valor's Rest graveyard of Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1126] = { id = 1126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hive in the Tower", description = "The hive needs to be addressed in Southwind Village, and I think I know a way to get at them.  It's been my experience that the silithid hives are very sensitive to their environment; this explains their attacks when hearing the death wails of the spirits.\n\nThe silithid are strongest in the tower - the one with the mass of wasps circling it.  Scale the tower and jostle the hive into activity.  Report back what you learn, but be careful!  If you uncover anything that might help, bring it to me.", progress = "Well, did it work?  You're still in one piece, which is good news.  Did you find anything?", completion = "What the... what is it?\n\nIt has the shape of a... box, maybe?  It's encrusted over something fierce.  Wait, there's a portion here that's exposed... is that a book underneath all this gunk?\n\nI think you've stumbled across quite the find here, {name}... well, at least I hope it is.  Perhaps it is a journal or a log from ancient times, preserved in this shell.\n\nI think I know a way to find out what this is.", objectives = "Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity. Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1127] = { id = 1127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fool's Stout", description = "So you want some Fool's Stout, eh?  Thinking of heading back to the races...?\n\nAll right, bring me more of Zanzil's mixture and I'll make some more stout for you.", objectives = "Bring 12 of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1130] = { id = 1130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melor Sends Word", description = "{name}, Melor Stonehoof has heard of your deeds, and has set a path before you.\n\nIf you wish to take it, then go to Thunder Bluff and speak with Melor.  You will find him on Hunter's Rise.", completion = "So, {name}, you have come.  Now, are you prepared to journey through distant lands?\n\nIf so, young {class}, then listen on...", objectives = "Speak with Melor Stonehoof in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1131] = { id = 1131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steelsnap", description = "At times we hunt for food.  At times we hunt for honor.  And at times we hunt to earn the Earthmother's teachings.\n\nBut the hunt I now set upon you is none of these things.  It is to slay a creature outside the Earthmother's blessing.\n\nThe hyena Steelsnap roams the Thousand Needles, south of the Barrens.  He is a tyrant, attracting other hyenas to him and spreading fear and bloodshed among more peaceful beasts.\n\nFind Steelsnap, {name}.  Find him, and defeat him.", progress = "Have you defeated the foul Steelsnap, {name}?", completion = "In defeating the creature Steelsnap, you have cleansed the Thousand Needles of a horrible taint.\n\nAnd that, {name}, is your lesson this day.", objectives = "Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1132] = { id = 1132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiora Longears", description = "Oh, to be at sea once again!  To feel the kiss of the wind, and to have the waves rock me like my blessed mother, long ago!\n\nOh, I wish I had your fortune, good {class}, for I see the sea in your future!\n\nIt's my job to tell eager souls of the land of Kalimdor, the land of opportunity!  If you're willing to try your luck across the sea, then take a ship from here to the lovely port of Auberdine.  Speak there with my partner, the elf, Fiora Longears.\n\nShe'll start you on your Kalimdor adventure!", sourceObjective = "Speak with Fiora Longears on the docks at Auberdine in Darkshore.Oh, to be at sea once again!  To feel the kiss of the wind, and to have the waves rock me like my blessed mother, long ago!\n\nOh, I wish I had your fortune, good {class}, for I see the sea in your future!\n\nIt's my job to tell eager souls of the land of Kalimdor, the land of opportunity!  If you're willing to try your luck across the sea, then take a ship from here to the lovely port of Auberdine. Speak there with my partner, the elf, Fiora Longears.\n\nShe'll start you on your Kalimdor adventure!", sourceObjectiveStatus = "unverified-source-field" }
quests[1133] = { id = 1133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Astranaar", description = "{name}, go to Astranaar.  I'm sure an eager member of the Alliance such as you can do some real good there.  Speak with Shindrell Swiftfire and offer your services.\n\nBut don't bother mentioning who sent you.  Shindrell does not know me...", completion = "You are here to offer your services to the Alliance, {name}?  We welcome the aid, for although its beauty remains... Ashenvale Forest is not the peaceful place it once was.", objectives = "Speak with Shindrell Swiftfire in Astranaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1134] = { id = 1134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pridewings of Stonetalon", description = "We are not in open war with the Horde, but our peace is fragile.  We often find their agents moving against us, but they do so covertly.\n\nOne such advance was revealed to us from hidden sources in Theramore, claiming that the orcs collect venom from the pridewings near Mirkfallon Lake, in the Stonetalon Mountains to the south.  Orc assassins then use the venom on their secret death raids against the Alliance!\n\nIf this is true, then we must stop them, {name}.  We must deny them their source of venom.", progress = "Do you have the pridewing venom sacs, {name}?  We cannot allow the orcs to use the beasts' poisons against us!", completion = "Thank you, {name}.  It saddens me to order the slaughter of creatures who may not willingly aid our enemies, yet it is my duty to do so.\n\nYour heart might weep for the pridewings you slew, my friend, but may your heart then swell in knowing that your allies are safe from the pridewings' venom.", objectives = "Bring 12 Pridewing Venom Sacs to Shindrell Swiftfire in Astranaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1135] = { id = 1135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highperch Venom", description = "As you may know, wyverns are often tamed by orcs for use as mounts.  But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself.  So if you're not afraid to do a little wyvern hunting, then... I have a job for you.\n\nThere is a place called Highperch in the land of a Thousand Needles, west of here.  The Highperch wyverns have a potent venom.  Potent, and valuable.", objectives = "Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1136] = { id = 1136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmaw", description = "{name}, it is now time for you to travel to far-off lands.  You are ready.\n\nYou now hunt Frostmaw, a yeti in the Alterac Mountains.  He is elusive, his white coat blending into the snows of his mountain home.  He rarely shows himself.\n\nBut I will show you how to entice a creature such as he.  Here, take this scroll.  On it I have written how Frostmaw may be lured.\n\nNow go, {name}.  Your journey is long and many challenges lay waiting.  When you return with Frostmaw's mane, only then is your task complete.", progress = "Have you been to the Alterac Mountains, {name}?  Did you face the elusive Frostmaw?", completion = "Both strength and cunning were needed to find and defeat Frostmaw, {name}.  You have both.\n\nYour path has taken you to the valleys of Thousand Needles and to the high mountains of Alterac.  It will one day lead you through all the Earthmother's lands, for such is the way of the hunter.", objectives = "Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1137] = { id = 1137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News for Fizzle", description = "Indurium has an amazing resistance to heat!  I'm sure it will work for Fizzle's pistons.  But he'll need true indurium ore, not just the flakes.\n\nTo get the ore, it must be mined from deep within Uldaman, on the northern borders of the Badlands.  That is the true source of indurium.\n\nSend Fizzle Brassbolts my regards, and tell him what I told you.\n\nSafe travels, {name}.  And it won't surprise me if we meet again -- once Fizzle learns of indurium he'll probably send you to Uldaman to acquire it!", completion = "{name}, you're back!  You found Martek?  You spoke with him?  What did he say?  Can he help??\n\nTell me, tell me, tell me!!", objectives = "Speak with Fizzle Brassbolts on the Shimmering Flats in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1138] = { id = 1138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fruit of the Sea", description = "I love crab.  Crabs are the fruit of the sea!  You can bake it, barbecue it, boil it, and broil it.  They're pan fried, deep fried, and stir fried.  There's crab salad, crab soup, crab stew, pepper crab, lemon crab, whipper root crab, and Ironforge surprise crab.  That's... that's about it.\n\nI'm here fishing right now, so I can't get any fine crab chunks.  You can pick them out of reef crawlers and encrusted tide crawlers.  You can make a lot with it.  You can bake it, barbecue it, boil it...", progress = "...lemon crab, whipper root crab, and Ironforge surprise crab.  That's about it.\n\nOh, hello there {name}.  Do you have them fine crab chunks I was telling you about?", completion = "Wow, these fine crab chunks are what I need.  Thanks {name}!  I found this while I was fishing a while ago, and I have no use for it.  Maybe you can do something with it.  It sure don't make any good crab dishes.\n\nI told you all about crabs, right?", objectives = "Collect 6 Fine Crab Chunks for Gubber Blump in Auberdine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1139] = { id = 1139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Tablets of Will", description = "We've slowed the Shadowforge clan by cutting them off from Blackrock Spire, but Hammertoe's quest is still unfulfilled. His death must not be in vain. He dreamt of finding the Tablet of Will: a stone shard inscribed with magic by the titans themselves to help imbue their creations with life--making them have a will of their own, or so the legends say.\n\nWe must still recover the Tablet before the Shadowforge clan finds it.\n\nReturn to Uldaman, find the tablet, and return here immediately.", progress = "Hammertoe's quest must be actualized, {name}. I owe him that much.\n\nYour return to Uldaman is imperative not only to that goal, but also to the safety of all dwarven kind. With the tablet in the hands of the Dark Irons who knows how powerful their army of golems would become.", completion = "<Advisor Belgrum shakes his head in disbelief as you hand him the stone shard.>\n\n{name}, this is amazing. I shall have this brought to the king's mages as soon as possible. They will want to study it to find out if the legends are true. But that is a discussion for another time: you have aided our people more than I would have ever expected--thank you.", objectives = "Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1140] = { id = 1140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tower of Althalaxx", description = "The writing of the orcs is little better than the scribblings of a child. Many of my order scoffed when I chose to learn their tongue, but I have found it beneficial to gain further understanding of my enemies.\n\nFrom Ilkrud's scribblings, it appears that Athrikus still possesses two soulgems, and they are being held in Night Run and Satyrnaar, satyr-held areas in northeast Ashenvale.\n\nBe careful out there, {name}, the satyrs' blood-soaked temples can be unsettling even for a seasoned {class} such as yourself.", completion = "Perhaps the satyrs have been allowed to persist in the forest for too long. I will speak with Elissa about it when next I travel to Auberdine.\n\nNonetheless, with the soulgems destroyed, Athrikus' power will be greatly diminished. We must seize on this opportunity to eliminate him and his cult.", objectives = "Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1141] = { id = 1141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Family and the Fishing Pole", description = "I love fishing.  The Blump family is known for fishing.  My name is Gubber Blump; I fish.\n\nThere's a kind of fish I like to catch around these parts called Darkshore grouper.  I used to go out on a boat to fish for grouper, but no boats have been going out since them mean ol' murlocs moved in.  I bet they been eating up all the grouper too.\n\nSay, you wanna help me catch Darkshore grouper?  I'd give you a bona fide Blump Family Fishing Pole if you did!  It's a real good pole to catch fish with.", progress = "There's plenty of good dishes you use Darkshore groupers for.  They're good to eat, but I think it's more fun catching them.\n\nYou caught any Darkshore groupers yet?", completion = "Them's some real nice groupers, {name}!  Thanks for helping me out!\n\nYou're at least as good of a fisherman as my cousin, Graun Blump.  She also has a beard and she smells kinda funny, but that don't do nothing to stop her fishing.  I reckon you have what it takes to use a Blump Family Fishing Pole.", objectives = "Catch 6 Darkshore Grouper for Gubber Blump in Auberdine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1142] = { id = 1142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mortality Wanes", description = "I have not long to live... so... so... weak.\n\n...the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel...\n\nBut before I... d-d-die...\n\n...my wife, Treshala... her pendant of bonding to me... stolen... by one of the f-f-foul aggressors...\n\nFind it p-p-please... and return it to Treshala in Darnassus...\n\n...along with w-w-word of my lonely... death.", progress = "What brings you to my home, {race}?", completion = "No!\n\n'Tis not fair. Oh, cruel and intolerable world!\n\nI must now carry this burden of grief and not let Heralath's work die with him.\n\nYou were brave to journey from such a dangerous place, {name}. But please leave me now.\n\nIn solitude I shall mourn.", objectives = "Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1143] = { id = 1143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tower of Althalaxx", description = "I see. Well, if what you say is true, then now is the time to strike. I believe Athrikus resides at the top of the tower. Be careful though, he is surrounded by many powerful warlocks, much more deadly than the ones you faced before.", progress = "Athrikus Narassin is an ancient and powerful warlock. Perhaps we should wait for Delgren's assistance, but he obviously had much faith in you to send you alone.", completion = "With the death of Athrikus, I hope that the demonic forces in this area will be driven back. I have no doubt that they will regroup and return, but then we shall be even more prepared to meet their threat.", objectives = "Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1144] = { id = 1144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willix the Importer", description = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that Mebok Mizzyrix was paying well for Blueleaf Tuber from this here pig pen. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.", completion = "Thanks again, friend! I told you I'd make it worth your while.", objectives = "Escort Willix the Importer to the exit of Razorfen Kraul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1145] = { id = 1145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Swarm Grows", description = "Many travelers who've come through the Crossroads helped me gather eggs from the Field of Giants, and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought.\n\nI need a courier to travel to Orgrimmar to meet Belgrom Rockmaul. It be no simple matter, and someone who would take the task seriously should go.\n\nBelgrom usually be found outside the warriors' guild house.", progress = "I envy you, {class}. You have the look of someone who's been outside the walls of Orgrimmar for a while.\n\nI myself would travel in the name of the Warchief if Thrall didn't have need of my skills here in the city. But he leads us well, and I trust his judgement--I remain here for as long as he needs me.", completion = "Ah, a note from Korran. He has been a loyal servant for some time now. I was wondering how his duties were going in the Crossroads.", objectives = "Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1146] = { id = 1146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Swarm Grows", description = "So, Korran has come to a similar conclusion about these insects--they seem to be a larger threat than we assumed.\n\nA few days ago a hunter returned to me from Thousand Needles nearly dead. He was with a raiding party sent to drive a dwarven excavation team out of the Shimmering Flats. During the attack, more of these insects erupted from a cave in the dig site and nearly killed the party.\n\nThey were led by Moktar Krin, and they've taken refuge on the border of the Shimmering Flats. Bring him this note.", progress = "War brings my group and I to the Shimmering Flats, {class}. What brings you here?", completion = "Don't mind the thundering echoes off the mountains' walls. The goblins and gnomes are out among the Flats racing one another in atrocities created by what they call science. There are bigger threats here in Thousand Needles, one of which killed more than half my war party.\n\nBut we remain here until we hear word from Belgrom in Orgrimmar. Until then, we hold our position here, and stay vigilant.", objectives = "Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1147] = { id = 1147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Swarm Grows", description = "Hmm. Seems Belgrom thinks those monsters are a threat. He wants them pushed back into whatever depths they crawled up out of.\n\nI guess killing the dwarves sent by the Explorers' League wasn't enough--now I have to send a half-dead war party into another battle. We won't be able to do it ourselves; not while we're in this condition. The dig site's to the south of here. There shouldn't be anymore dwarves to deal with. Feel up to wielding a blade or staff and doing your part to aid us?", completion = "Ha! That ichor you're covered in actually makes you prettier, {name}! It certainly does make you reek at the same time though. Don't stand too close to the kodo; you'll either start a stampede or cause them to go into heat.\n\nI think my companions would agree that your smell alone is proof you've done your part to help us against those insect creatures. Thank you, {name}.", objectives = "Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1148] = { id = 1148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts of the Swarm", description = "You inspect the carapace carefully. As you turn it over in your hands you realize that the chitinous plating is interlaced in such a way that makes it incredibly strong. It's unlike anything you've ever seen. You inspect the rest of the corpse further and realize that these creatures are very powerful and highly evolved.\n\nLooking down at the carapace again, you think that Korran would enjoy studying more of these creatures. It could help him figure out what these creatures are, and where they come from.", progress = "Ah, it been a long time since you've come to see me, {name}. What can I do for you today? You be looking like you've seen the face of battle recently. Good... good for the Horde and good for you. The more battle you've seen, the more helpful you'll be; stronger, too.", completion = "Ahh, you've seen Moktar recently? He always be lookin' out for me. I'm sorry to hear he spends his time watching over his little war band instead of seeing battle, but I'm sure he be takin' great joy in killing members of the Explorers' League.\n\nYou be smart to bring me these specimens, {name}. Along with the eggs we be findin' in the Field of Giants, these should give me a good start in figuring out what these insects are, and what they be wantin'.", objectives = "Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1149] = { id = 1149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Faith", description = "So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew.\n\nMany facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you.\n\nIf you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether.\n\nThe first is a Test of Faith.", sourceObjective = "If you have faith, leap from the planks overlooking Thousand Needles.", completion = "It is not until faced with unforeseen adversity that we begin to see how strong our spirits are. You took the leap of faith even though you had no guarantees that you would survive. Your mind is open, and your spirit is prepared for what is to come.\n\nIf you are willing, then the next of your tests is ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[1150] = { id = 1150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Endurance", description = "I'm pleased to see your courage remains steadfast in light of what you've already done. Since your faith is intact, the time has come to test your body.\n\nFirst is a test of endurance. Go to the Roguefeather Den west of Freewind Post. Make your way to the depths of their lair and destroy their foodstuffs. By then you should have provoked their fury, and if you are able to survive long enough, Grenka Bloodscreech herself will come for you--kill her and bring me her claw to complete your test.", progress = "You must be prepared spiritually, physically and mentally for the challenges that lie ahead of you.\n\nToo often do we rush forward before we are ready. I consider it my duty to the youth, no matter which tribe they belong to, to prepare them for the dangers they may face after they leave the sanctity of their home.", completion = "Grenka was powerful, even by {race} standards. You should be proud of your accomplishment this day.\n\nDuring your test of faith you displayed strength of spirit, and now you have shown endurance in battle by taking on the Roguefeather harpies, but the time has come for a new test.", objectives = "Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1151] = { id = 1151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Strength", description = "During the time of the Old Gods, elementals inhabited much of this world. They worshipped the Old Gods, and the Gods, through their power, kept the elementals bound to this world. When the Old Gods were banished, the elementals faded from our world and now only return at the bidding of powerful mages.\n\nThere are exceptions though. Some elementals were powerful enough to remain here on their own. One such elemental is Rok'Alim.\n\nTo test your strength, find Rok'Alim in Thousand Needles and slay him.", progress = "Rok'Alim is also called the Pounder by the centaur tribes in Thousand Needles because of the thundering his fists make as he pummels the creatures brave, or stupid, enough to stand in his path.", completion = "The Test of Strength is done. You have shown strength and bravery, and you are now prepared for the final test before these rites are completed.", objectives = "Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1152] = { id = 1152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Lore", description = "Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.\n\nIf you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, {name}.\n\nWhen you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, {name}, the night elves may wish to impede your test.", sourceObjective = "Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", completion = "The days and nights grow colder throughout the world as goblins rape the land, and the night elves point fingers at the younger races. The Forsaken and orcs are not the only ones to blame for the hardships found throughout Kalimdor and Lordaeron. Many of the intelligent races have contributed to the world's pain. Dorn knows this, and he has sent you to me because you have shown the attributes necessary to realize it also.\n\nNow you stand before Braug.", sourceObjectiveStatus = "unverified-source-field" }
quests[1153] = { id = 1153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Ore Sample", description = "{class}, you have done well in helping me in the past. The warchief is pleased thus far with what I've accomplished, and asks me to continue with renewed determination. My honor dictates that I give you proper recognition to the warchief for all you have done, but first I would ask you for your help again.\n\nTravelers recently came from the south from a place called Thousand Needles. There they killed a kobold who had an unusual ore sample, but they would not sell it. I want a sample of that ore to examine.", progress = "I saw the travelers again--the ones that would not sell me a sample of the ore. I spit at them for not helping the warchief.\n\nMay they die in battle like cowards and not like warriors as should be the right of all people who ally themselves with the Horde.", completion = "A good sample, {name}. A good sample indeed.\n\nThose travelers can no longer lord over me the ore they found, now that you have been successful.\n\nI shall get to work on it immediately. If it proves strong enough, I will send a weapon crafted from the material back to the warchief to show him our success.\n\nI shall not forget your help, {class}.", objectives = "Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1154] = { id = 1154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Lore", description = "You have passed Dorn's tests, and now you seek to pass your next trial. Very good. But up until now, your challenges have been childish. It is easy to test your body--your mind is another matter completely.\n\nI shall explain it simply: find the book I name, study it, and answer my question about its contents.\n\nWhat book, you must be asking? The Legacy of the Aspects. It can be found at the bottom of Dor'danil in southern Ashenvale, protected by the dead druids and their slayers.", progress = "Bring me the book after you've studied it. I will not ask you your question until after you have given me the book.", completion = "This is the book I named. There is hope you will answer my question correctly then... unless you've forgotten to study its contents.\n\nWhen you are prepared, speak to me again and I shall ask a question of you.", objectives = "Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1159] = { id = 1159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Lore", description = "Well done, {name}. You have passed the first portion of the Test of Lore, but there is still another question to be answered. But that question is not mine to ask.\n\nSeek out Parqual Fintallas in Lordaeron City. He was a great historian for the humans before the Plague overtook him. Now he continues to seek enlightenment, but of a different nature.\n\nHe will have another requirement of you before he asks you anything, but you have done masterfully thus far--I'm sure you will overcome his obstacle.", completion = "Braug sent you? Impossible.\n\n<Parqual looks you up and down.>\n\nBraved Dor'Danil, took a leap of faith, fought and overpowered a powerful elemental? Bah! You're probably a farce; some adventurer that overheard talk in a tavern. And now you think you have what it takes to pass my test. So be it... {class}.", objectives = "Find Parqual Fintallas in Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1160] = { id = 1160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Lore", description = "I will tell you what you must seek, and I will even ask you my question, but not because you wish to prove yourself. Knowledge is far more important than strength. Even as others seem to pass you by in ability, your knowledge of the world will be more valuable.\n\nGo to the Monastery in the north of Tirisfal Glades. In the library there, a book called Beginnings of the Undead Threat resides. It was used by the now-corrupt paladins there to train them to fight my kind.\n\nBring it to me.", progress = "I hope you made the Scarlet Crusade suffer some before stealing the book from them.\n\nMy views of their kind are not unwarranted. The Crusade may have been followers of the Light at one time, but now, they seek to destroy any creatures that have not sided with their religion. They believe all undead, Forsaken or otherwise, must be cleansed, and those traveling in their lands must either be insane, or subject to the undead's powerful magics. Idiots. Idiots and fools; all of them.", completion = "This is the book I sent you to search for.\n\n<Parqual slowly caresses his hand over the top of the book as he stares down at it.>\n\nSo now you wish a question to prove your mind is as powerful as your body and spirit. If you have studied the book long enough, then I shall ask you your question and you can be done with these tests!", objectives = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1164] = { id = 1164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Steal From Thieves", description = "The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!\n\nMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, her and her lousy children had the audacity to steal the only precious belongings I had left.\n\nI don't care about the things they stole any more. What I want now are their heads!\n\nKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.", progress = "Kill them all and bring me their heads!", completion = "You stand before me as a figure of vengeance, and I bow down before you in thanks.\n\nWith that cow's death, and knowing that their seed will no longer spread over the face of Azeroth, I can put my energy into something more lucrative. I hope you looted their farmstead after you finished them off.", objectives = "Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1166] = { id = 1166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "verlord Mok'Morokk's Concern", description = "Bow before Overlord Mok'Morokk!\n\nRexxar make me mighty leader of Stonemaul Clan!\n\nMe good leader. Me keep clan safe.\n\nBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.\n\nLeave old home so fast, me forget stuff. Tiny {race}, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!", progress = "Me thirsty for grog. Me miss snuff too. Where is strongbox? You go get for Overlord Mok'Morokk.\n\nGo find south in old home. Me too busy leading ogres to get.", completion = "You good {race}. Me miss things very much. Me like you now.", objectives = "Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1167] = { id = 1167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tower of Althalaxx", description = "Before confronting Athrikus, it would probably be wise for you to consult with Balthule. I have no doubt he has been vigilant in his watch of the Tower, and he may have information about recent developments.", sourceObjective = "Speak with Balthule Shadowstrike near the Tower of Althalaxx.", completion = "Ah, it's good to see you again, {name}! The strangest things have been happening around here, I'm glad you showed up!\n\nIt was very strange, {name}. Everything seemed normal--well, as normal as things get around here--and then suddenly there was a blinding flash of light from the upper room of the tower. Then came the screams. The cries split the air, and lightning struck the ground from time to time. What's going on?", sourceObjectiveStatus = "unverified-source-field" }
quests[1168] = { id = 1168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Army of the Black Dragon", description = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.\n\nBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.\n\nOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.\n\nMe call Stonemaul Ruins home. Me like it in the south. This place not home.\n\nHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.", completion = "You kill many of the black dragon army. You brave {race}.\n\nMake Tharg happy.", objectives = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1169] = { id = 1169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "dentifying the Brood", description = "Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.\n\nWhy the puzzled stare, {name}? Expecting me to speak like an uncouth ruffian merely because I am an ogre?\n\nNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...", progress = "With the hearts and tongues of scorched offspring of the black dragon army, I can decipher what wretched beast introduced her spawn into our home. Perhaps with a greater knowledge of our aggressors, we can seek to destroy them once and for all and reclaim Stonemaul Village from ruin.\n\nOf course, convincing Mok'Morokk to move his lethargic, fat mass out of this muck hole is going to be an epic quest in and of itself...", completion = "'Twas a perilous affair, no doubt, collecting all of these hearts and tongues. I shall delve into the depths of the arcane to trace the origin of the black menace which has descended upon our former home.", objectives = "Draz'Zilb in Brackenwall Village would like you to bring him 7 Searing Tongues and 7 Searing Hearts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1170] = { id = 1170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Brood of Onyxia", description = "Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?\n\nThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.\n\nNotify Mok'Morokk at once! Action must be taken.", completion = "Why you tell me 'bout dragons? Me no like dragons. Me like it here. No dragons here.", objectives = "Speak with Overlord Mok'Morokk in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1171] = { id = 1171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Brood of Onyxia", description = "You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.", completion = "That lazy coward!\n\nMok'Morokk displayed strength when Rexxar was our leader. But soon after Rexxar's departure Mok'Morokk fell prey to temptations of power. Rather than lead, he demanded. He does not serve his people but rather expects us to serve him.\n\nSomething must be done.", objectives = "Speak with Draz'Zilb in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1172] = { id = 1172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Brood of Onyxia", description = "Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.\n\nMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.\n\nWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.\n\nAs for Mok'Morokk... I have other plans for the sod.", completion = "Splendid! It will be sometime before Onyxia can produce more eggs.\n\nOn behalf of my people, I thank you, {name}.\n\nI have asked much of you so far. Perhaps you can do the Stonemaul Clan one last service.\n\nMok'Morokk is not fit to lead us. Tharg would make an excellent leader but is hindered by his injuries and age. Drive Mok'Morokk from this place by force. Only then can we appoint a new leader to return us to our proper home in the south.", objectives = "Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1173] = { id = 1173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "hallenge Overlord Mok'Morokk", description = "You dare challenge Overlord Mok'Morokk?\n\nHaw!\n\nMe crush tiny {race}!\n\nYou tell me when ready for good beating.", completion = "That cowardly fat mass Mok'Morokk fled like a scared child. You have done a great service, {name}.\n\nNow my people can appoint a new leader, one who will help us reclaim our old home once and for all.", objectives = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1174] = { id = 1174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomes Win!" }
quests[1175] = { id = 1175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bump in the Road", description = "After the big crash with the goblins' Red Thunder racer and a basilisk, Kronkrider hired me on to take care of the track. I don't know what all the animals out on the flats are feeding on to grow so big, but we have to be careful to thin them out so they won't wander onto the track when a race is going on.\n\nTell you what. If you want to go out and make a little profit, go out and remove the basilisks from the area.", completion = "I hope you didn't kill any of the basilisks on the tracks themselves! It takes a long time for the carcasses to decay in the sun, and I'd rather not have to take a shovel out to clean up.", objectives = "Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1176] = { id = 1176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Load Lightening", description = "When it comes to racing, every bit counts! Whether it's a minor tweaking on the power output, a slight slackening on the tension coils, or lightening the weight of the frame, you have to take everything into account.\n\nWe use vulture bones for a lot of the minor structural tweaks we make to our racers, which offer the perfect balance of strength and weight. Even better, it's easy for us to get more, as the salt flats are littered with vultures.\n\nBring me some and I'll give you a good price on them.", progress = "Do you have those bones for me? I was just about to start working on lightening the steering rig, but I don't want to open her up without all the parts I need.", completion = "Great! I can get the crew working on this right away. Thanks, {name}!", objectives = "Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1177] = { id = 1177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry!", description = "Mud big ogre.\n\nMe hungry.\n\nGo bash fishy. Bring Mud food.\n\nYou feed Mud or Mud eat you.", progress = "Gimme food or me eat you.", completion = "Me like fishy head!\n\nMe no eat you now.", objectives = "Mudcrush Durtfeet in northern Dustwallow wants 8 Mirefin Heads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1178] = { id = 1178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Sponsorship", description = "Our racing team is the pride of goblins everywhere. You'd be surprised at some of the people who contribute in one way or another to our team.\n\nYou know Gazlowe? He tracks down parts from around the world for us. He even came down to work on one of our rigs once!\n\nA few weeks ago, he said he'd send us a new prototype fuel regulator but it hasn't come yet. He's usually very prompt... Maybe you wouldn't mind going to Ratchet to ask him about it? I wouldn't be so pushy, but the gnomes are gaining on us!", completion = "Pozzik sent you, huh? You know, Pozzik was one of the most respected tinkerers in Undermine before he retired to start working on the racers.\n\nThe first thing he did when he joined the team was develop the two engine model racers. Could be that the businesses will suffer without him working with the Tinkers' Union, but who cares, right? There's nothing like the races!", objectives = "Speak to Gazlowe at Ratchet in The Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1179] = { id = 1179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brassbolts Brothers", description = "You ever heard of the Shimmering Flats?  It's a stretch of salt flats way over in Kalimdor, just south of the Thousand Needles canyon.  It's a great place for racing because, well, it's so flat!\n\nA couple of gnome brothers are out there, friends of mine, trying out their new rocket car, and from what I hear it's fast!  Heh, so fast that their pilots keep crashing.  Giving themselves concussions.\n\nSo they asked me for some Siege Engine helmets, but I have duties here.  I can't make the trip!\n\nCan you?", progress = "Watch where you're stepping!  Watch watch watch!!  This is delicate stuff you see here, and if we're to win then it must all work perfectly!", completion = "Ah!  Longbeard sent you with a load of helmets!  Hooray!\n\nNow maybe we can talk a pilot into driving our car...", objectives = "Bring the crate of crash helmets to Wizzle Brassbolts at Mirage Raceway in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1180] = { id = 1180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Sponsorship", description = "Back to what you came here about. I know I promised Pozzik that I'd deliver a new fuel regulator for him, but I still haven't received it yet. Revilgaz over in Booty Bay said he'd have it shipped over, but it might be it slipped through the cracks somehow.\n\nIf that's true, there's not much we can do about it. We can at least find out if it was dispatched from Booty Bay.\n\nCheck in with Wharfmaster Lozgil over there, he should be able to check the cargo records.", completion = "Shipments to Ratchet? Let me just check the logbooks...\n\nNo, the most recent shipment I have on record of going out to Ratchet were boots from Drizzlik. Hasn't been much else, other than building supplies and tools. Definitely no race parts.", objectives = "Speak with Wharfmaster Lozgil in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1181] = { id = 1181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Sponsorship", description = "I'm afraid I can't be of much more help to you, {name}. If you'd like to follow up on it more, I'd suggest you go hit up the Baron himself. If there's anyone who knows Revilgaz's business, it's Revilgaz.\n\nYou'll find him at the tavern across the harbor, top floor.", completion = "Oh, sure of course I know what you're talking about. Nope, can't help you though. Some of my men were supposed to go track down the blueprints for the fuel regulator, but they came back empty-handed.", objectives = "Speak with Baron Revilgaz in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1182] = { id = 1182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Sponsorship", description = "See, the Venture Company shredders out in Lake Nazferiti (in northern Stranglethorn) have been equipped with a new model fuel regulator. I was thinking that Pozzik would be able to take advantage of it, if he could get some details. Unfortunately, Cozzle, the foreman out there, appears to be a little more clever than I gave him credit for.\n\nYou seem like you might have more luck finding the blueprints though. I know he keeps them in his house, but they're almost certainly under lock and key.", progress = "Much as I hate to admit it, that gnome team they have out there is pretty good. Our boys need every edge they can get.", completion = "Now, let me just get a copy of these blueprints for my own notes and you can bring these straight to Pozzik. Wouldn't want him to think that one of his sponsors was abandoning him.", objectives = "Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1183] = { id = 1183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Sponsorship", description = "You should be all set to go. Give Pozzik my regards and tell him that if he ever needs anything, not to hesitate to ask. I'll be waiting for the news that he breaks the track record soon!", progress = "{name}! Did you manage to track down the fuel regulator?", completion = "I was hoping that it would be already assembled, but this does present the unique opportunity to improve on the design from the ground up. Thanks, {name}. I'll be able to sketch up some improved schematics, build the thing, and have it installed real soon.", objectives = "Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1184] = { id = 1184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts of the Swarm", description = "Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly.", sourceObjective = "Return to Belgrom Rockmaul in Orgrimmar.", completion = "I'm appreciative of your efforts, {class}. The warchief will enjoy hearing how tenacious you have been in your duties.\n\nOh, of course I will mention your name to him. He speaks to me often and values my opinions greatly.\n\nGo now, I have much to do. And if you speak to Korran soon, and he has news of these creatures, then return to me--I would think they are a threat that must be taken seriously.", sourceObjectiveStatus = "unverified-source-field" }
quests[1185] = { id = 1185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Chitin Was...", objectives = "Hey, it's you again!  Well, I mean you - as in the you that is {name}!  Yes - that you!\n\nHey, let me start over!\n\nThat object you found in Silithus - it was in fact a book.  It was a journal written in a very ancient dialect of what we now call the Darnassian tongue.  It'll take a while, but I'm going to go over it very thoroughly.  I thought you should know that what you found was extremely valuable for the Circle.\n\nThe den mother's all excited and everything!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1186] = { id = 1186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eighteenth Pilot", description = "I'm going to be busy with working on integrating this new fuel regulator to our racer designs, but if you'd like to help out the team some more, talk to Razzeric. He's our pilot--well, our eighteenth pilot, to be exact--and he likes to add his own little modifications to the racers.\n\nHe's a little off his rocker, though, so try not to act too surprised.", sourceObjective = "Speak with Razzeric on the Shimmering Flats in Thousand Needles.", completion = "You're the {race} that's been helping Pozzik out, right? I was like you once, running around the pit area, helping with whatever work the mechanics would let me do.\n\nNow look at me! The goblin racing team's pilot extraordinaire!", sourceObjectiveStatus = "unverified-source-field" }
quests[1187] = { id = 1187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razzeric's Tweaking", description = "Pozzik's a great mechanic, I know that, but he's afraid to just load on the firepower and grab on for the ride. Not me, though.\n\nAfter Pozzik finishes with a racer, I take a little time to put my own modifications on--you know, loosening up the controls, removing parts of the frame, and adding more juice!\n\nI ordered a seaforium booster from Shreev at the Gizmorium in Gadgetzan, but apparently the zeppelin it was being sent on crashed in Dustwallow Marsh! I gotta have it, {name}!", progress = "How'm I supposed to show my face around the track without a little extra kick to get me going? It's a travesty, I tell you.", completion = "Just take a look at this beauty! Fifteen pounds of solid seaforium power! Once I get this strapped on to the side of my racer, I'll be around the track so fast I'll beat the gnomes twice!", objectives = "Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1188] = { id = 1188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety First", description = "But wait, what's this? Shreev left the safety on. That will limit the amount of power I can draw from the booster at any time. I told him I wanted it off! This is no good.\n\nYou have to take this to the Gadgetzan Gizmorium in the Tanaris Desert and have Shreev remove this.", progress = "As I'm sure you know, the Gizmorium can service all of your tinkering needs! How can I help you?", completion = "Only Razzeric would take a look at this and say that I'd somehow put some sort of safety lock on it. This booster is almost completely seaforium explosives. I already modified it so that more of its payload would be delivered upon use, but Razzeric is never content unless he goes to eleven!", objectives = "Bring the Seaforium Booster to Shreev at Gadgetzan in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1189] = { id = 1189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety First", description = "There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track.\n\nWould be a shame, too, if that happened. Who knows if our nineteenth driver would be any good?", progress = "Can you believe Pozzik put a bucket of sand on the racer? How am I supposed to hit my maximum speed with a bucket of sand under the seat?", completion = "Now that's more like it! I wish I could see the look on the gnomes' eyes when they see me set this baby off.\n\nToo bad I'll be too busy pulling off a new course record!", objectives = "Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1190] = { id = 1190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping Pace", description = "The Brassbolts brothers have discovered a new building material, that's the only explanation that makes sense. Their cars have been operating faster than before, but their designs, and all the other data we've gathered from their runs is identical.\n\nWhat we do know, is that Rizzle Brassbolts has been focused on the plans for this new discovery almost constantly.\n\nZamek can create a diversion for you, so that you can steal those plans from them.", completion = "Scribbled in a hasty, hurried hand, a scroll of notes and designs for the refinement of some raw material.", objectives = "Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1191] = { id = 1191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zamek's Distraction", objectives = "Let's go!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1192] = { id = 1192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Indurium Ore" }
quests[1193] = { id = 1193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Broken Trap" }
quests[1194] = { id = 1194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rizzle's Schematics", description = "Rizzle's schematics describe the process of the refinement of indurium ore. From his scrawls, it is apparent that indurium ore is being obtained from the dwarven excavation site of Uldaman in the Badlands.\n\nMuch of the other notes relate to the heat resistant properties.\n\nUsed as a paperweight for the plans is a hunk of what appears to be unrefined indurium ore.", completion = "Indurium? Interesting... If it is capable of resisting heat to the degree that you say, it would explain the performance increase the gnomes have displayed of late.\n\nThis sample you've brought to me will be invaluable, also. I will be able to perform some tests on this, but I'll need more for this to actually be of any use to us.", objectives = "Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats in Thousand Needles.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1195] = { id = 1195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sacred Flame", description = "The Galak centaur in the Thousand Needles are protecting an artifact from the time of the centaurs' creation.\n\nWe would like to retrieve it, but we require a phial of water from one of the night elves' moonwells.\n\nTo collect the water, you will first need to obtain one of the phials carried by the dryads near the Raynewood Retreat in the heart of Ashenvale Forest. There is a moonwell near the western bank of the Falfarren River, south of the main road, where you can fill the phial.", progress = "Once we have the filled phial, we can send it along to my associate, Rau, in the Thousand Needles. He was the one who requested the phial of water, so he'll better know how we can make use of it.", completion = "Very good. This should fill Rau's request just fine. Could you deliver this to him? You might enjoy spending some time out in the Needles.", objectives = "Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1196] = { id = 1196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sacred Flame", description = "Bring the filled phial to Rau Cliffrunner at the Freewind Post in southeastern Thousand Needles. You can get to the Thousand Needles by taking the Great Lift at the southern edge of the Barrens.\n\nI wouldn't be surprised if you can help us out further.", progress = "I don't suppose you've been sent by Zangen, hm?", completion = "Hm, yes, this phial of water will serve our purposes perfectly. Because of the shared ancestry of the dryads and the centaurs, the water of the moonwells will enable us to breach the protection of the eternal flame surrounding the centaur relic.", objectives = "Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1197] = { id = 1197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sacred Flame", description = "Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it.\n\nYou will find Splithoof Crag, the centaurs' stronghold, to the north of here. The flame is kept in Splithoof Hold, a heavily guarded part of the crag.\n\nBe careful, though, the Galak centaur have great numbers here, and will be rather reluctant to surrender something so dear to them.", progress = "I am eager to put my hands upon the Cloven Hoof. Have you taken it yet?", completion = "I sense a strange energy emanating from the Hoof... I have no doubt that we will discover surprising new information about the centaur from its study.\n\nMy thanks, {name}. Now I must begin to decipher the mysteries you have brought to me.", objectives = "Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1198] = { id = 1198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Thaelrid", description = "Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps to the west.\n\nMy role here is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been days now since I sent a scout to check on the activity inside Blackfathom Deeps. Scout Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out Thaelrid for me, {name}.", sourceObjective = "Seek out Scout Thaelrid inside Blackfathom Deeps.", completion = "Dawnwatcher Shaedlass was good to send you. There is indeed a wicked plot underway in this corrupted place.", sourceObjectiveStatus = "unverified-source-field" }
quests[1199] = { id = 1199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Falls", description = "Empowered by the ancient rites of the chaotic Old Gods, the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps to the west.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", progress = "Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight's Hammer.\n\nHave you made any progress in ridding their presence?", completion = "You are no doubt of brave and noble blood, {name}. The Argent Dawn commends you for your efforts against evil.", objectives = "Bring 10 Twilight Pendants to Sentinel Aluwyn at the Blackfathom Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1200] = { id = 1200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Villainy", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Ashelan at the Blackfathom Camp, {name}, please.", progress = "Time is a precious commodity, {class}.\n\nMy role here in Darnassus is to ensure that the Argent Dawn thrives and that the evil forces encroaching upon Kalimdor are thwarted.\n\nState your business quickly or be on your way.", completion = "Kelris has eluded us for quite some time.\n\nIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him dead or missing.\n\nBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.\n\nBy the light! To sacrifice someone to a servant of an Old God for one's personal gain is beyond reproachful!\n\nYou have done a great deed, {name}. I salute you on behalf of the Argent Dawn.", objectives = "Bring the head of Twilight Lord Kelris to Ashelan Northwood at the Blackfathom Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1201] = { id = 1201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theramore Spies", description = "The Horde and Alliance hold an uneasy truce.  Outlying skirmishes and covert actions are taken by one side against the other, and it is our duty to ensure the Horde is on top!\n\nNow is the chance to do just that.\n\nAlliance infiltrators have taken positions east of Brackenwall Village.  They spy on the village and report our movements to Theramore, which we cannot allow.\n\nHunt down the infiltrators and slay them.  Send a clear message to their superiors that we will not tolerate their spies' presence!", completion = "Good work.  Their infiltrators are skilled, but they're not good enough to escape the watchful eye of the Horde!", objectives = "Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1202] = { id = 1202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Theramore Docks", description = "{name}, two of our spies were sent to steal documents from a ship at the Theramore docks.  They gained the papers but were discovered, and were forced to throw the documents into the sea.\n\nOne spy later escaped, but was unable to recover the prize.  He reported his failure to me, and I now charge the task to you.\n\nThe documents are in a footlocker, in the waters somewhere beneath the Theramore docks.  Find those documents, {name}, and bring them to me.", progress = "Did you find the documents, {name}?  They hold information vital to the stability of the Alliance and, hence, vital to the security of the Horde.", completion = "I commend you, {name}.  This was not an easy mission.  But the documents you gained are valued greatly by our superiors.", objectives = "Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1203] = { id = 1203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl Needs a Blade", description = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a sword.  I call it a swing blade.\n\nYou help me?  Those fish-men, you know, murlocs or whatever they're called.... There's one they call Razorspine, carries a big sword, lives north of here near the beach. That's the sword I need!\n\nBut don't sleep on this.  What I'm cutting won't keep forever...", progress = "You have my blade??", completion = "That's a good blade.  It has a good swing.  It's a good swing blade.  Thank you.  Thank you, thank you, thank you!!!  Now I want to try it....  \n\nLater.  I'll try it later.  But like I was saying... thanks.", objectives = "Bring Razorspine's Sword to \"Swamp Eye\" Jarl at Swamplight Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1204] = { id = 1204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mudrock Soup and Bugs", description = "I'm working on a dish I call \"Mudrock Soup and Bugs.\"  I still need the major ingredients, and... well, I don't think I'd last long trudging through Dustwallow Marsh!\n\nSo, {name}, can you do some hunting for me?  First, I need the tongues of Mudrock turtles.  You can find Mudrocks along the coast, mostly around the bay.\n\nBut I don't want just any tongues!  I hear that the tongues of some Mudrocks are forked...\n\nThey say the forked tongues have a distinct flavor, and I want that flavor in my dish...", progress = "Did you get the forked tongues?", completion = "These will do fine!  Thank you, {name}!\n\nNow I'll try different cooking techniques on these tongues to find the best way to bring out their flavor.\n\nEventually I'll have a dish worthy of serving at the Blue Recluse in Stormwind!", objectives = "Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1205] = { id = 1205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadmire", description = "Deadmire is an ancient crocolisk in Dustwallow marsh.  And it is his time to die.\n\nOld bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver.\n\nYet now he lives in constant, maddening pain.  You must end the life of this noble creature, {name}.  You must lead Deadmire to peace.", progress = "Do you have the tooth of Deadmire, {name}?  Have you ended the creature's suffering?", completion = "Very good, {name}.\n\nI am sure the hunt was not easy, but it is good to know the beast's pain has finally ended.", objectives = "Bring Deadmire's Tooth to Melor in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1206] = { id = 1206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl Needs Eyes", description = "Eye juice is good juice for drinking.  Too bad most critters only have two eyes.\n\nBut spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already.\n\nDarkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?", progress = "Where are those eyes?", completion = "You got the eyes!  You got the eyes!  Tasty, tasty spider eyes!\n\nSome eyes... when you stare at them they stare back. Eat those last.  They keep you company... out in the swamp.\n\nHello, little spider eyes.  Hello!  You taste like chicken.  Gooey, salty chicken!\n\nMmmh.", objectives = "Bring 20 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1218] = { id = 1218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsh Frog Legs", description = "I like cooking.  Good swamp cooking.  Fried green frog legs and the like.\n\nAnd I'm all out of legs. The manor is overrun with frogs, though. Giant marsh frogs. Think you could bring me some of those legs? Nothin' to it, really. Just bop 'em on the head and bring me the legs.\n\nThen I'll make a stew and stew it up and suck it down and give you some too.\n\nDo you like stew?", progress = "Spice.  We could all use some spice in our life.  You agree?", completion = "Ah, that's the spice!  Now here's some swampy good stew.", objectives = "Bring 10 Marsh Frog Legs to \"Swamp Eye\" Jarl in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1219] = { id = 1219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Orc Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is written in orcish... and it looks important.", progress = "Do you have a report to make?", completion = "Hm... I can't read orcish very well, but this looks like a report... written by an orc spy!", objectives = "Bring the Spy's Report to Lieutenant Aden in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1220] = { id = 1220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "aptain Vimes", description = "Captain Vimes should see the orc report you found, {name}.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!\n\nThe captain is in the barracks, on the northeastern side of Theramore Isle.", progress = "You have something for me?", completion = "A report from an orc spy!  How did you find this?  No matter -- let's see what it says...", objectives = "Bring the Spy's Report to Captain Garran Vimes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1221] = { id = 1221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueleaf Tubers", description = "Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.\n\nAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.\n\nIt won't be easy, but if you get me some tubers I'll pay you handsomely.", progress = "Do you have the tubers, {name}?", completion = "Great, you got them!  I can sell these to my contacts for a bundle!\n\nThanks for the delivery, {name}!  You are a great partner.", objectives = "Grab a Crate with Holes.\nGrab a Snufflenose Command Stick.\nGrab and read the Snufflenose Owner's Manual.\n\nIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.\n\nBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1222] = { id = 1222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinky's Escape", description = "Great, finally something that doesn't want to eat me!\n\nI need help handling the critters around here, and you fit the mold, <buddy/lady>.\n\nThe cook Morgan Stern is researching a new recipe, and he sent me out here to gather bogbean leaves.  I guess he thinks they're tasty.\n\nAnyway, while looking for a bogbean plant... I got myself surrounded!  Can you help me out of here, and watch my back as I look for the bogbean?", completion = "Mr. Ignatz was just here with the bogbean leaves, and he told me you helped him out of some real trouble.\n\nThank you, {name}.  I will ask my uncle to treat you to a feast the next time you visit the Blue Recluse in Stormwind.", objectives = "Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1238] = { id = 1238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.\n\nAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.", progress = "You have something for me?", completion = "Good work, {name}.  Our agent, Marg Nighteye, was stationed outside Theramore.  He was charged to spy on the city.  \n\nThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp...", objectives = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1239] = { id = 1239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Severed Head", description = "Vigorous digging reveals the head of a male orc, raggedly severed at the neck.  His lips are frozen in a snarl, and its dark eyes stare defiantly.", progress = "You have another matter to report, {name}?", completion = "This is the head of Marg Nighteye!  As I feared, he is dead.\n\nLook at the wound on his neck!  Could a weapon have made that ragged cut, or did some beast slay our agent?\n\nThis is a mystery we must solve, {name}.  We must discover if Marg's death was at the hands of the Alliance!", objectives = "Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1240] = { id = 1240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Troll Witchdoctor", description = "We must know the events surrounding Marg's death!  And the only way to do that, {name}, is through the witch-magic of trolls.\n\nBring Marg's head to Kin'weelay in Stranglethorn Vale, at the Grom'gol Base Camp.\n\nKin'weelay is the most powerful witchdoctor of the Darkspear trolls.  If anyone can speak to Marg Nighteye's spirit, it is he.", progress = "There is an angry spirit about you, brother.  What brings you to Kin'weelay?", completion = "Ah, I now see.  The spirit of this orc is bound in our world, boiling with rage from a task yet undone.\n\nWell, let us have words with this angry orc...", objectives = "Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1241] = { id = 1241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "Recently a diplomat was sent to Theramore to meet with Jaina Proudmoore. That diplomat never arrived.\n\nI believe the Defias are involved in this plot, but I'm not sure how. The diplomat's disappearance still eludes public attention, but it can't remain that way for long.\n\nAgents of the king are already scouring the city for clues, but I have my own contacts I would like involved.\n\nIn the Valley of Heroes is an old friend of mine named Jorgen. Find him, give him this note, and follow his instructions.", progress = "Hmph, you better have good reason to interrupt a man and his fishin'. I don't take kindly to peddlers, let alone beggars.", completion = "Hmm... <Jorgen looks up at you through squinted eyes.>\n\nAll right. I'll help ya, but not because I want to, but because I'm obligated.\n\nAnd let's get one thing straight: you're knowin' far more than you should to begin with. Let's keep this our little secret, and don't go blabbin' at any taverns about anything you find out. Understand?", objectives = "Find Jorgen in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1242] = { id = 1242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "Take this here note to Elling Trias. Don't say nothin' else to him. Just be polite and wait for him to respond. And don't worry, he will.\n\nI'm gonna only impress this on ya once more, {name}: treat this matter seriously, and keep your yapper shut.\n\nYa can find Trias at his cheese shop, Trias' Cheese, in the Trade District. Good luck.", progress = "Hello, {name}. Is there something I can do for you? Perhaps you'd like to try some of our special Trias cheddar? Or a block of Darnassian bleu?", completion = "I'm sorry, a letter for me? Well, I'll be... not often you get a delivery that's not a crate or barrel when all you do is work. Let's see what this is about.\n\n<Elling looks up at you while he opens the letter.>\n\nYou look a little tense, you okay, {name}?", objectives = "Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1243] = { id = 1243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "Jorgen, you ol' sonuva.... So, that's how it's going to be, huh?\n\nAll right, I can deal with that. I hope he finds the Twisting Nether that much sooner!\n\nHere's what's gonna happen, {name}. I'll start using my contacts here, but you're doing most of the footwork so I save some coin.\n\nHead to Darkshire in Duskwood and find Watcher Backus--he usually patrols the north road right outside of town. Just tell him you're looking into any Defias activity for me and he'll help you out with any information he can.", progress = "Not too safe to be traveling about in the woods, {name}. Be careful, and if you see anything suspicious or dangerous, contact the Watchers immediately. Don't try and take anything on yourself. We're not responsible for anything terrible that might happen to you.\n\nBut we both know you're gonna ignore me and fight whatever comes out of the darkness anyway, don't we? Haha, yeah, you adventurer types... all the same.", completion = "Oh, Trias sent you, huh? That's a little different.\n\nFeel free to fight whatever monstrosities come at you from the darkness. I'm sure you'll be able to handle it pretty easily if you're the type to be hanging around with the likes of him.\n\nSo, what does my friend need of me on such a gloomy day as this?", objectives = "Give the Sealed Note to Watcher Backus in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1244] = { id = 1244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "Defias activity? Well, there's always some activity; even if they keep to themselves we consider them a threat.\n\nBut now that I think about it, there was a recent sighting that seemed odd. It must have been a couple weeks ago, but some of their agents had gathered around Addle's Stead. From the report, I'd guessed something big went down.\n\nWhy don't you check there first and bring me back anything you find?\n\nThe farmstead is south of the road from Westfall just as you enter Duskwood.", progress = "Be careful out there, {name}. I know Trias was the one to send you here, but that doesn't mean there isn't anything lurking out in the woods that couldn't cause you some trouble... especially with you investigating the Defias.", completion = "You're back safe and sound. Couldn't ask for much more than that, could you?\n\nNow, let's see what we have here. This looks pretty official as far as any Defias documents I've seen. But it could be a dupe just to throw you off track of whatever it is you're looking for.", objectives = "Find the Defias Docket and return it to Watcher Backus in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1245] = { id = 1245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "Whoa, this looks way too complex to be something to just lead you astray. I shouldn't even be looking at this stuff. Take it to Trias--he'll be able to make sense of it. And DON'T let anyone get in your way. This is bigger than me. It might even be bigger than him, but we'll see.\n\nAnd do me a favor, {name}, don't tell anyone I helped you. If my superiors found out I knew about any of this and didn't share it with them they'd probably hang me.", progress = "I see you're back, and in one piece. We both know you're not here for cheese, so let's cut out the pleasantries. Was Backus any help, or have you even left for Duskwood yet?", completion = "Yeah... this is an interesting read. Jorgen and DeLavey were smart to bring me in on this.\n\nSeems the Defias have been trying pretty hard to complete this plan of theirs. Hmm... what's this? \"Fist\"? That's a familiar name.", objectives = "Bring the Defias Docket to Elling Trias in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1246] = { id = 1246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "Yeah, now that I think about it... Dashel... Dashel something... What was his name? FIST! Dashel Stonefist. They call him Fist in some circles--probably on account that he likes to get in brawls.\n\nYou can find him in Old Town usually--right smack dab in the center of it. Go talk to him. If you have to, use a sword or something heavy and blunt to persuade him to open up some. And don't hesitate. If he's in this as deep as these papers suggest, then he's not going to give you any information willingly.", completion = "What?!\n\nYou come into me alley and ask questions about me personal business? Business which you obviously have nothing to do with.", objectives = "Speak to Dashel Stonefist in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1247] = { id = 1247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "So yeah... um... I might know something 'bout that meeting at Addle's Stead. Happened a few weeks back I think. I really didn't have any part in it. Me part was done when plan A failed... damn adventurers.\n\nThe guy we got on the inside for plan B came out of Menethil; guy called Slim. That's all I know regarding their backup plan.", completion = "Good to see you're still alive, {name}. So, it went well with Dashel then, huh?\n\nI've been reading up more on this plan of theirs, and although it doesn't state the name of the diplomat they were after, it does talk about this plan B they enacted after failing on their first attempt to capture him.\n\nThis Slim that Dashel mentioned doesn't have any other name written here, but if you say he's in Menethil, then that's a start.", objectives = "Speak to Elling Trias in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1248] = { id = 1248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "A contact of mine retired in the Wetlands at the harbor city of Menethil. He should be willing to help on your word alone if you tell him you're working for me. His name is Mikhail. He mentioned becoming a bartender before leaving Stormwind a few years ago.\n\nSpeak to him, find this Slim, and find out if there's anything else to know about this kidnapped diplomat. We need to find out where they've taken him, or at least who he is. The docket doesn't mention anything about their plans after he's captured.", completion = "Welcome, welcome, welcome, {name}. Good of you to join us. Perhaps an ale today? Or some mutton?\n\nName your pleasure and I'll see to it that you're taken care of. My name is Mikhail, and I look forward to serving you.\n\nHmm? What's that? Trias? Keep your voice down, my friend. This isn't something for the whole tavern to hear about.", objectives = "Speak to Mikhail in the Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1249] = { id = 1249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "You say Elling sent you here? Well then, the hospitality I expressed is now tenfold. Anything you need, just ask. I will do my best to aid you.\n\nHmm, Slim, you say? Not sure the name sounds familiar, but I'll keep my eyes out for him.\n\nDon't look now, {name}, but the gentleman over by the exit is looking over here. He's listening to our conversation a little too intently if you catch my meaning? If I were you, I'd do what you can to subdue him before he makes a break for the door.", completion = "Caught him, huh? Good for you. I'm surprised that was Slim.\n\nI'll be honest, I never thought I'd miss the excitement of some of the more devious underground activities. I guess old habits die hard. Don't mention that to Elling--he'd probably try and get me to come back to Stormwind if he heard I missed the action.\n\nI'm glad I could at least be of a little service to you while you were in Menethil. If you need anything else, just ask.", objectives = "Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1250] = { id = 1250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "The Defias didn't pay me well enough to die for their cause. They took the king. Yeah, the king of Stormwind, not some lowly diplomat. He was on his way to Theramore to meet with Jaina Proudmore--it was a big deal apparently, and a big secret. But it's not just the Defias that are involved. They're working with someone. I think they knew this was bigger than them.\n\nMy part was just to get their man on board the king's ship while it was in the harbor. The guy's name was Hendel. That's all I know. I swear!", completion = "THE KING?! I mean... the king? The real king? Are you joking? You didn't mention you were looking for the king's kidnappers. I didn't even hear he was missing--that would explain his son being crowned some.\n\nI'll send word to Elling right away. He'll want to know you're on the trail.\n\nI would never have guessed Jahn would sell out Stormwind for some lousy coin. Even a rogue's got to have honor when it comes to some things.\n\nThe key now is to find this Hendel. And I think I can help with that.", objectives = "Speak to Mikhail in the Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1251] = { id = 1251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", progress = "What's that you have there, {name}? Evidence from the remains of the Shady Rest Inn?", completion = "I grant that humans have strange decorating tastes, but would they use a plain iron shield to adorn their fireplace? Perhaps this shield was placed there by the ones who burned the inn.\n\nA warning? A threat?", objectives = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1252] = { id = 1252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", progress = "Have you found anything of interest at the Shady Rest Inn?", completion = "It's never good news when a guard's badge is brought to me.\n\nSometimes it's a man or woman who's fallen in battle, and I'm left to bring the news to the grieving family. Other times we never find out what happened to them. And other times it's even worse than that.", objectives = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1253] = { id = 1253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", progress = "Have you found evidence from the site of the Shady Rest Inn?", completion = "Hm, I'm no expert with the construction of arms and armor. Their use, yes, but not their making.\n\nThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn.", objectives = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1258] = { id = 1258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... and Bugs", description = "Another component of my new recipe is the shelled leg of a giant crab.  And the crabs they have in Dustwallow -- spiny rock crawlers they call them -- will be perfect!\n\nThe shell of the crab leg is a key element of the dish's presentation so I need pristine, unscarred legs.  An adult crab might only have one or two such legs, and I need a lot in order to research my dish.\n\nHead on over to the rocks surrounding Theramore and get me those legs!", progress = "My research with the Mudrock tongues is progressing nicely.  I trust your crab hunt goes well?", completion = "These are wonderful specimens, {name}!  The shells are in perfect condition, and the meat is pink and tender.  The blood of a chef is in your veins, I'm sure of it!", objectives = "Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1259] = { id = 1259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ieutenant Paval Reethe", description = "I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.\n\nHe should be able to tell you who this Reethe is with a quick check of his books.", completion = "Hello, {name}. You'd like information about a specific member of the Theramore guard? Reethe, was it?\n\nJust give me a moment to find the right book.", objectives = "Find out more about Reethe from Adjutant Tesoran in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1260] = { id = 1260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "organ Stern", description = "I'm developing a new menu for the restaurant.  It will be filled with rural dishes with a \"bayou\" theme.  I think my clientele at the Blue Recluse will love them!\n\nI sent my nephew Morgan to Theramore, a city on the edge of the Dustwallow Marsh.  He's there gathering recipes from the locals, and I must know what he found so far.\n\nThe trip to Theramore is long.  Too long for me.  But I bet a young {class} like yourself would jump at the chance to travel, yes?", completion = "Oh, my uncle sent you, did he?\n\nWell I've been researching recipes and I have some leads, but I need help.\n\nHelp from someone willing to get his feet wet.", objectives = "Speak with Morgan Stern in Theramore.I'm developing a new menu for the restaurant. It will be filled with rural dishes with a \"bayou\" theme. I think my clientele at the Blue Recluse will love them!\n\nI sent my nephew Morgan to Theramore, a city on the edge of the Dustwallow Marsh. He's there gathering recipes from the locals, and I must know what he found so far.\n\nThe trip to Theramore is long. Too long for me. But I bet a young {class} like yourself would jump at the chance to travel, yes?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1261] = { id = 1261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marg Speaks", description = "Cursed muckshell!  You can't kill Marg!  Ah, but I am dead.  So it must have slain me...\n\nBut my mission!  My mission!  You, {name}, must complete it.\n\nWhile near Theramore, I spied a group of Alliance soldiers camped on the beach.  And one soldier wore a pendant... a pendant laden with more gems than any soldier could afford!\n\nThat night I snuck into their camp and stole the pendant, but on my return to base a muckshell crab-man killed me!\n\n{name}, you must find that muckshell and recover the pendant!", progress = "{name}, did you discover Marg's fate?", completion = "This pendant was worn by a soldier of Stormwind??\n\nThank you, {name}.  You have revealed the secret of Marg's death.  But this pendant is a new mystery to solve, one that may have dire effects on the Alliance, and the Horde.", objectives = "Bring the Jeweled Pendant to Nazeer in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1262] = { id = 1262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Zor", description = "It is strange that the pendant Marg stole was in the hands of common soldiers.  Perhaps its owner was in disguise, or perhaps the soldiers themselves stole it!\n\nRegardless of which is true, this is a noble's pendant and we must discover its true owner if we are to unravel its mystery.\n\nTake the pendant to Zor Lonetree in Orgrimmar.  He is well schooled in Alliance politics, and will know if this pendant has a history among the nobles of Stormwind.", progress = "You traveled from Brackenwall Village in Dustwallow?  How fares Nazeer, and how fare his efforts in the marsh?", completion = "This pendant was crafted with great skill and precision, {name}.  No orc would covet such a jewel...\n\nBut many humans would.\n\nI will have this pendant studied.  In time let us hope that its mysteries will be revealed to us.", objectives = "Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1263] = { id = 1263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning Inn <CHANGE TO GOSSIP>" }
quests[1264] = { id = 1264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "The beginning of every month the Kul Tiras Marines all get paid and usually leave Theramore for somewhere else. A lot of them come here to womanize, carouse, and just have a good time. One of those groups I'd consider regulars here at the tavern, and I believe this Hendel is among them.\n\nCommander Samaul in Theramore would be able to help you find him if Hendel's still stationed there. He's completely loyal to Proudmoore, but if you drop Elling's name, he should help you out... discreetly.", completion = "A pleasure to meet you, {name}. I am Commander Samaul. I'm in charge of Miss Proudmoore's forces here in Theramore.\n\nAlthough I'm quite busy, if you have any questions, please feel free to speak up. I might have to keep it short, but there's no reason for me to be rude if you need my help.\n\nIf you plan on traveling out of the city, I'd suggest you be careful. Besides ogres, orcs and murlocs, the southern part of the swamp is filled with black dragons.", objectives = "Find Commander Samaul in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1265] = { id = 1265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "Hendel? Yes, I know the man. But why would you need one of my soldiers?\n\nElling sent you to find him? Hmm, I don't like the sound of that. Elling wouldn't have you come to me first if your business wasn't troubling. I understand if you can't tell me what this is about, but know this: I have a duty to protect these lands. If you're going to cause a disturbance, then I suggest you inform me of whatever you can.\n\nI believe Hendel was stationed at the first tower outside of Theramore. Be cautious.", completion = "The man you seek, the one known as Hendel, is not here. Other sources have brought to the Lady Proudmoore information I believe you already know. She has asked me to find you, and give you aid in your venture. If you would allow it, I will tell you where to find Private Hendel so we can bring him to justice.", objectives = "Search Sentry Point for any sign of Private Hendel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1266] = { id = 1266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "Private Hendel is to the west of here. He's currently on guard duty protecting some of Theramore's infiltrators while they rest. They've been keeping tabs on the Horde base, Brackenwall, and looking for anything else that might threaten our borders.\n\nYou should have no problem finding him; just look for the tents along the road.\n\nI have another matter to attend to, but I shall catch up to you soon enough. You can always find me in the Lady Proudmoore's tower if you have any problems.", completion = "Hello, citizen. This is a dangerous place to be wandering about. I wouldn't hang around too long if you value your life.\n\nIf you keep your questions short, I'll see if I can help you. Just keep your eyes open for any of those filthy ogres. Rumor has it there's a Horde base somewhere in the swamps. The infiltrators are doing what they can to find it, but the process has been slow going and we've had little progress.", objectives = "Find Private Hendel in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1267] = { id = 1267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", completion = "Let me be first to thank you for all you've done, {name}. You have been an incredible blessing to my people and the people of Stormwind. I am sorry I couldn't make your acquaintance under better circumstances.\n\nUnderstand also that I cannot overtly thank you for your efforts, but I assure you again, it is appreciated.\n\nWhen you visit Theramore in the future, seek me out and I shall try to keep you appraised of the situation.\n\nThank you again, {name}.", objectives = "Speak to Jaina Proudmore in Dustwallow Swamp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1268] = { id = 1268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "uspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", completion = "Hoofprints... It could have been the quilboar, I suppose. Or maybe even the centaur. Their presence in the Barrens is not insignificant, and I would not think it a stretch to commit such an act.\n\nDid I tell you? It wasn't just that the inn was burned down... The owner's woman and pup were killed. Bad business, that.\n\nNonetheless, I will send Kagoro to find where the tracks lead.", objectives = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1269] = { id = 1269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", progress = "Have you found any leads on what happened at the Shady Rest Inn?", completion = "I know this human, Paval Reethe. Pathetic, even for his kind. He deserted his fellow soldiers and is now hiding out in the woods.\n\nI sent Ogron out to track him down. Some of the others suspect he's been stealing from our supplies. I think I saw Ogron heading off to the southeast.", objectives = "Bring Reethe's Badge to Krog in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1270] = { id = 1270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinky's Escape", description = "Great, finally something that doesn't want to eat me!!\n\nI need help handling the critters around here, and you fit the mold, <buddy/lady>.\n\nA goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am.\n\nToo bad I got myself surrounded before I found the bogbean!  Can you help me out of here, and watch my back as I look for Mebok's plant?", completion = "Stinky was here with the herbs I ask of him, and he told me you helped him out of a bind.  Good work!  A friend of Stinky's is a friend of mine!\n\nHe asked me to give you this if I ever saw you, right before he walked back south toward the marsh.", objectives = "Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1271] = { id = 1271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feast at the Blue Recluse", objectives = "My nephew said you aided him with his research in Dustwallow, and that you helped his associate out of a tight spot.  Well, we Sterns stick together and we don't ignore our friends!\n\nSo wash your hands, {name}, because we're about to throw a party in your honor!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1272] = { id = 1272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Reethe <CHANGE INTO GOSSIP>" }
quests[1273] = { id = 1273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "uestioning Reethe", description = "It took a long time, but I found Reethe. He hide good for a human.\n\nOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.", completion = "Hmph. It is good that Reethe will no longer be lurking around the swamp, but it is a shame that humans are built so frail that he could not recover from a little arrow wound.\n\nIt seems that this thread of the mystery has led nowhere, and we must look elsewhere.", objectives = "Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1274] = { id = 1274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "Excuse me, <sir/madam>. Bishop DeLavey asked me to approach adventurers that might be able to help him with a delicate matter.\n\nIf you could quietly head to Stormwind Keep and speak to him at your earliest convenience, I'm sure he would appreciate your help. Again, please be discreet. It is a matter of some importance.", completion = "Hello, {name}. I am Bishop DeLavey.\n\nNo doubt if you're asking me about my business here in the keep then young Thomas has succeeded in requisitioning you to help our kingdom. He has always been adept at following my requests.\n\nI'm afraid I don't have time to elaborate much, so allow me to be blunt... and please, try to keep this from becoming common knowledge.", objectives = "Find Bishop DeLavey in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1275] = { id = 1275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researching the Corruption", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the Sin'dorei are headed toward. In Blackfathom Deeps, just to the west, you will find both satyr and naga.", progress = "Once I have enough samples to study, my true work can begin. With the corrupted brain stems of both the satyr and naga of Blackfathom Deeps I can try to draw a correlation between the mutations.\n\nPerhaps with that gained knowledge we can prevent the blood elves from delving deeper into deformity and evil.", completion = "You have traveled far and undoubtedly faced great peril.\n\nYour actions have been selfless. 'Tis for the good of all Azeroth that you help me with my research. I thank you, {name}, for all that you have done.\n\nNow if you'll excuse me I have much work to do....", objectives = "Relwyn Shadestar at the Blackfathom Camp wants 8 Corrupt Brain stems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1276] = { id = 1276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Black Shield", description = "Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.\n\nIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.\n\nPerhaps he can tell you more about the shield he crafted.\n\nIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.", progress = "Hello there, {class}. Something I can help you with?", completion = "Yes, you are certainly correct. This is a shield that I made.\n\nI'm afraid there's not much more I can tell you though, {name}. I craft so many different shields and sets of armor, I can't keep track of them all.", objectives = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1281] = { id = 1281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jim's Song <CHANGE TO GOSSIP>" }
quests[1282] = { id = 1282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "hey Call Him Smiling Jim", description = "I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place.\n\nLook, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to. He's stationed on the top floor of Foothold Citadel, the large barracks to the east of Lady Jaina's tower.", completion = "James Hyal's his real name. He opened an inn at the edge of the Barrens. Wanted to make a nice place for travelers to stop over...\n\nMight be he was thinking too big, but the inn did do well for a while. Then we lost control of the roads in the marsh, and the ogres took over.\n\nJames was too stubborn to give up his dream for safety within our walls, and the Shady Rest Inn was burnt to the ground. We're investigating, but haven't had much luck. If you want to help out, see what you can find in the rubble.", objectives = "Speak with Captain Garran Vimes on the top floor of Foothold Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1283] = { id = 1283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire at the Shady Rest <CHANGE TO GOSSIP>" }
quests[1284] = { id = 1284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "uspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", completion = "Hoofprints, eh? It is true that there is an extraordinary amount of centaur activity in the lands near the Dustwallow Marsh. In brief excursions into the Barrens, we found their camps and holdings dotting the area.\n\nI'll send out Falgran Hastil, one of our trackers, to see if he can find where the tracks lead.", objectives = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1285] = { id = 1285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "aelin's Men", description = "Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.\n\nJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...\n\nListed as missing.", completion = "Missing? That would be Tesoran's kind way of saying traitor.\n\nNo doubt he's one of those fools so blindly loyal to Admiral Daelin that he turned traitor.  Isn't that a delicious irony? The deserters accuse us of betraying the Alliance.", objectives = "Return the information about Reethe to Captain Garran Vimes in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1286] = { id = 1286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Deserters", description = "It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.\n\nThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.\n\nThe local lieutenant seems to be Balos Jacken. See if you can get some information out of him.\n\nBe warned, {name}. He may be a tough nut to crack.", completion = "Did Vimes send you? Couldn't do his dirty work himself, could he...", objectives = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1287] = { id = 1287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Deserters", description = "Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?", sourceObjective = "Speak with Captain Garran Vimes in Theramore about Reethe.", completion = "I will send Lieutenant Caldwell to deal with the deserters at Lost Point. In addition, I will instruct him to find Reethe. The marsh is not so big and trackless that he should be unable to find him.", sourceObjectiveStatus = "unverified-source-field" }
quests[1288] = { id = 1288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vimes's Report", description = "You've done some good work, {name}, best I've seen from an amateur.\n\nLady Proudmoore asked that I keep her apprised of this delicate situation, and I haven't spoken to her for some time now.\n\nI was going to deliver my report to her later, but it seems more fitting that you should be the one to speak with her about it. You can probably answer her questions better than I could.", objectives = "Bring Vimes's Report to Lady Jaina Proudmoore in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1301] = { id = 1301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ames Hyal", description = "Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?", sourceObjective = "Speak with Vincent Hyal in Menethil Harbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[1302] = { id = 1302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ames Hyal", description = "My brother James went with Lady Proudmoore across the sea. Last I heard, the fighting had settled down over there, and James was setting up an inn somewhere on the continent. Wherever he is, I'm sure he's doing good business. Damn fine cook he was.\n\nI haven't heard from him for a while now--too busy with his inn, I'd wager--but the clerk in Theramore could probably point you to him. Look for him on the top floor of that keep near the middle of the city. What's it called... Foothold Citadel, that's it.", sourceObjective = "Speak with Clerk Lendry at Foothold Citadel in Theramore.", completion = "James Hyal, James Hyal... Why does that name sound so familiar?\n\nOf course! The Shady Rest Inn incident. If you have any information about what happened there, I would urge you to speak with Captain Vimes about it. He's handling the investigation.", sourceObjectiveStatus = "unverified-source-field" }
quests[1318] = { id = 1318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Gordok Business", description = "Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince!  Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever!  Yar, I show you!", objectives = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\n\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1319] = { id = 1319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Black Shield", description = "I'm sorry I can't be of much help, {name}, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.\n\nTake the shield to him, and see what he can tell you.", progress = "Something for me to look at?", completion = "Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it's certainly not my work.", objectives = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1320] = { id = 1320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Black Shield", description = "Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.\n\nThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.", completion = "That's not much information to work on, but we'll have to keep it in mind. Hopefully some of the other pieces of this mystery will fall into place, and paint a more helpful picture of what happened.", objectives = "Speak with Captain Garran Vimes in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1321] = { id = 1321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Black Shield", description = "Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...", progress = "Something for me, {class}?", completion = "This is good shield. Very strong, heavy, good. But Do'gol don't need it. I make shields, not buy them, {name}.\n\nYou should know that.", objectives = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1322] = { id = 1322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Black Shield", description = "Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.\n\nI need acid to make it clear. Venom from the darkmist spiders would do good. The spiders have taken over an old mine, the Darkmist Cavern, northwest of the village. Get me some of their sacs and I can clean this up.", progress = "Did you get them sacs from the spiders?", completion = "I don't like spiders that are so big I can't sit on them and squish them.\n\nThanks for getting them, {name}. Now I rip them open and pour them onto the shield...", objectives = "Acquire 5 Acidic Venom Sacs for Do'gol in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1323] = { id = 1323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Black Shield", description = "Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...\n\nHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.", completion = "Mosarn? Sounds familiar... I can't put my finger on it. Maybe it'll come to me later.\n\nIt probably isn't important. A shield can come from anywhere and not mean anything...", objectives = "Talk with Krog in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1324] = { id = 1324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "What?! You come here accusing me of allying with the Defias, and think I'll just stand here while you insult me?! Something tells me you've had this coming for a long time.", completion = "I assure you, we're all quite upset about current events, but allow us to take him back to Theramore for some questioning, and we'll see about finding the King.\n\nI'm sure my lady Proudmore would like to thank you for your help. Speak to her when you have a moment.", objectives = "Defeat Private Hendel in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1338] = { id = 1338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpike's Order", description = "There is a dwarven armorsmith whose work I admire greatly.  His name is Furen Longbeard, and his skill is unmatched.  I need a new shield, and I must have one of his!\n\nThe problem is... Furen is far to the south, in the dwarven district within Stormwind.  In human lands!  I can't imagine why he would live there, so far from Ironforge.  The humans must pay him a king's ransom to keep him there!\n\nSo, if you want to travel and don't mind making some money, then will you send Furen my request for a shield?", progress = "A letter from the dwarven lands?  I wonder who would call from so far to the north...\n\nPlease, let me see the order.", completion = "Ah, a request from one of the Stormpikes.  That's a proud clan, full of quality dwarves.  Rich ones, too.\n\nThank you, {name}.  I'll get to work on Mountaineer Stormpike's shield by the end of the day.", objectives = "Bring Stormpike's Request to Furen Longbeard in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1339] = { id = 1339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mountaineer Stormpike's Task", description = "I hear Mountaineer Stormpike is looking for a runner.  Someone to do a little traveling for him.  How about it?  Are you the {race} for the job?\n\nIf so, then you'll find Stormpike at the top of the northern guard tower.", completion = "That's right.  I have a task that I can't do while I'm guarding.  In fact, it'll take you far from Loch Modan.\n\nYour perfect chance for adventure!", objectives = "Speak with Mountaineer Stormpike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1358] = { id = 1358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sample for Helbrim", description = "A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor.  He would be very interested in a sample of the wolf hearts Renferrel sent me.\n\nHelbrim is stationed in the Barrens, in a village known as the Crossroads.  To reach him, you must travel via zeppelin to the orc capital of Orgrimmar, then travel south, by foot, to Durotar.  Head west into the Barrens, and you will soon reach the Crossroads.", progress = "You have a package for me?", completion = "Ah, very good.  If initial reports are true, then the toxicity of these hearts could lead to further advances in our knowledge of poisons.\n\nThis is a welcome delivery, {name}.  Your reward is well earned.", objectives = "Bring the Wolf Heart Sample to Apothecary Helbrim in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1359] = { id = 1359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinge's Delivery", description = "The wolf hearts you acquired possess a quality unseen in similar specimens.  There is a toxicity to them that should be deadly to the very wolves in which the hearts beat!\n\nIt's quite incredible, and we must study it further.  I kept a few samples of the hearts acquired.  Take them to my colleague, Apothecary Zinge.  You will find her in our headquarters in the Undercity.", progress = "You have something for me?", completion = "Ah yes, the heart samples of which Renferrel spoke.  I am eager to experiment with these... it is always of interest to the Royal Apothecary Society when new forms of toxins are discovered.", objectives = "Bring the Wolf Heart Samples to Apothecary Zinge in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1360] = { id = 1360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaimed Treasures", description = "I had myself a fine job as a digger at the Uldaman excavation site in the Badlands... that is until those blasted troggs showed up.  I escaped with my hide barely intact, and nothing else.  In the chaos, I left my most treasured possession.  It's safe from the troggs in my chest, sure, but it's right in the thick of 'em.\n\nI'd be in your debt, both in honor and coin, if you could fetch it for me!  A chest with my name on it is at the end of the North Common Hall.  That's the one you need to get in.", progress = "Well now, we're you able to get slap around those troggs long enough to get into my chest and nab my treasure?", completion = "Ah, I feel complete again - thank you kindly.\n\nSome dwarves may treasure the luster of metal, and some may treasure the glint of gems... but a Stoutarm without a treasured stein in hand is hardly a Stoutarm at all!", objectives = "Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1361] = { id = 1361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regthar Deathgate", description = "A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads.\n\nAnd sharpen your weapons.  Desolace is a place torn by war.", completion = "Yes, I am recruiting.  This mission leads into Desolace, against the centaur there.  I will be brief so that you may quickly begin.", objectives = "Speak with Regthar Deathgate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1362] = { id = 1362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kolkar of Desolace", description = "The Kolkar centaur live in Desolace, and their forces have spread into the Barrens.  This is a known fact and we have Horde agents dealing with them here.\n\nBut as long as the centaur are strong in Desolace, they will always pose a threat.  It is time we rid ourselves of that threat.\n\nSpeak with Felgur Twocuts at Ghost Walker Post in Desolace.  He was sent to gather intelligence on the centaur.  He will know how to best deal with the Kolkar of Desolace.", completion = "You are here on orders from Regthar?  Then you are here to deal with the centaur.  Good.\n\nI hope you're rested.  I don't know how our campaign against the centaur will end, but I know the struggle will be long.\n\nHave a seat, and listen.", objectives = "Speak with Felgur Twocuts at Ghost Walker Post in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1363] = { id = 1363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazen's Behest", description = "As caretaker of the works here in the library of the Academy of Arcane Arts and Sciences, it is my responsibility to ensure all the magical tomes and scrolls are accounted for at all times. Who knows what folly would unfold if some of these enchanted texts were to fall into the wrong hands?\n\nWhich reminds me... my assistant, Dellis, made a horrible mistake last week. He's quite able in the library but incompetent when he leaves the gates of Stormwind. Be a hero, and help old Dellis out, would you?", sourceObjective = "Speak with Acolyte Dellis in Stormwind.", completion = "It wasn't my fault. Really it wasn't.", sourceObjectiveStatus = "unverified-source-field" }
quests[1364] = { id = 1364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazen's Behest", description = "Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep.\n\nBut I had never been to the Blasted Lands before! The journey was frightening!\n\nWhen I got to the Swamp of Sorrows, I made a wrong turn and ended up surrounded by horrible plant-like swamp creatures. They lurched as if to attack me so I ran. But in my haste I dropped the essay. One of the beasts took it I am sure.\n\nCould you please try to retrieve it and deliver it to Mahar Ba?", progress = "What brings you to Nethergarde Keep, {race}?", completion = "Ah, most splendid!\n\nFor some time I had feared my request for Khadgar's Essays on Dimensional Convergence had been overlooked by Master Mazen of the Academy of Arcane Arts and Sciences.\n\nHe must be bogged down with requests considering the many strange happenings going on.\n\nNow, if you'll excuse me, I need to begin my research at once. To finally glimpse the insight of one as great as Khadgar excites me to no end.", objectives = "Retrieve Khadgar's Essays on Dimensional Convergence and deliver them to Watcher Mahar Ba in Nethergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1365] = { id = 1365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Dez'hepah", description = "The Kolkar are not the only centaur of Desolace.  Many clans wander these dry plains, fighting and dying against each other.  And it is good that they fight among themselves, for they are strong and brutal.  If the centaur united against us, they would be a fierce foe.\n\nWe must deal with them before they unite.\n\nYour first task is to disrupt the Kolkar clan.  Do this by killing its leader, Khan Dez'hepah.\n\nThe Kolkar Village is northeast of here.  Go, and may fortune go with you.", progress = "{name}, have you defeated Khan Dez'hepah?", completion = "Well done.  This swift act against the Kolkar is an effective show of strength, and strength is what the centaur understand best.\n\nThe death of the Kolkar leader will not only disrupt that clan, but give pause to the others.", objectives = "Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1366] = { id = 1366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Centaur Bounty", description = "Now that you scared the centaur clans, it's time to bleed them.  When traveling Desolace, hunt centaur.  I don't care which clan you hunt.  Just gather ears.  A hoard of ears.\n\nBy weakening their numbers you will weaken their resolve, and stamp out any thoughts of expansion.\n\nGood hunting, {name}.", progress = "How is your collection of ears, {name}?  Large?", completion = "By now, the centaur must know your name.  I'm sure they know it, and respect it, and fear it.  And just as they know you, they know the banner under which you ride.\n\nThe banner of the Horde.", objectives = "Bring 15 Centaur Ears to Felgur Twocuts in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1367] = { id = 1367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magram Alliance", description = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Magram then slay their foes, the Gelkis.  This will earn you respect among the Magram.  When you earn enough, then meet with the Magram spokesman Warug, on the outskirts of the Magram Village, in southeast Desolace.", completion = "The Gelkis cry when they hear your name, {name}.  They fear you and they hate you.  They hate you like they hate the Magram!\n\nMaybe you are strong like the Magram.  We will see...", objectives = "Gain a Friendly reputation with the Magram, then speak with Warug.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1368] = { id = 1368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelkis Alliance", description = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Gelkis then slay their most hated rival, the Magram.  After you earn the respect of the Gelkis, meet with the Gelkis shaman Uthek the Wise, on the outskirts of the Gelkis Village, in southwest Desolace.", completion = "The earth speaks to me.  And it says you have killed many Magram.  This is good.\n\nIf you are a friend of the Gelkis, then listen.  I have more tasks for you.", objectives = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1369] = { id = 1369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Tears", description = "The Gelkis think our centaur mother, Theradras, protects us.  They are stupid.  No one protects the centaur.  The Magram do not need protection!  We are the strongest!\n\nShow the Gelkis they are stupid.  Go to the cave in their village.  They hoard crystals in that cave, the tears of Theradras.  Destroy the tears and bring me the broken pieces!", progress = "If you are not our enemy, then you will do what I ask!", completion = "You got the tears!  Now the Gelkis will know that Theradras will not help them.  She will not cry when we crush them!  The Magram will rule!\n\nYou are smart to help us, {name}.  We are the strongest.", objectives = "Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1370] = { id = 1370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Supplies", description = "When we are not at war, we hunt for meat.  Meat gives us strength, and full bellies fight harder than empty ones.\n\nIt is the same with the Magram.  They store extra meat so they may fight longer between hunts.  If you raid their village to the east and take their stores of meat, then their strength will fail.", progress = "Return after you further prove your worth to the Gelkis!", completion = "Good.  I can hear the loud Magram bellies grumble from their village, far away!\n\nI will give this meat to the Gelkis.  And we will fight for many days without rest.\n\nWhat you did is good for the Gelkis, {name}.", objectives = "Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1371] = { id = 1371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gizmo for Warug", description = "Long ago, a little gnome came to Desolace.  He had horses and a cart, and the cart held strange things.  Funny things.  Things that burned different colors.  Things that moved and weren't alive.  I killed the little gnome, but before that... he made me laugh.\n\nI kept my favorite thing from his cart.  It was a human made of wood and it waved at me until I hit it and broke it.\n\nI want a new one.  Get me a new one!", progress = "If you are not our enemy, then you will do what I ask!", completion = "Yes, this is what I had!  I will make it move again.  It makes me laugh!", objectives = "Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1372] = { id = 1372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing But The Truth", description = "Our expeditionary force was sent at Varimathras's behest to survey lower Azeroth.\n\nWhile out scouting I noticed a human Infiltrator spying on Beggar's Haunt. Before I could apprehend him, some of our orcish... brethren... captured him and took him to Stonard, their stronghold in Swamp of Sorrows.\n\nI want to... help... our orcish allies. They did not see our camp here but nonetheless I want to lend a hand.\n\nWork with Faustin here to develop a... truth serum for our friend in Stonard.", sourceObjective = "Speak with Apothecary Faustin at Beggar's Haunt.", completion = "Zraedus was just telling me about the nosey little Infiltrator before you arrived.\n\nQuite a problem, indeed. The last thing we need is a busybody sniffing around Beggar's Haunt.\n\nI am sure the orcs of Stonard would be quite anxious to hear what our friend has to say. Seeing that they are our allies, ahem, we must help them to get any information they can from the human.\n\nWork with me, {name}, and we will deliver a truth serum to Stonard.\n\nFor the Horde!\n\n...did I get that right?", sourceObjectiveStatus = "unverified-source-field" }
quests[1373] = { id = 1373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongeku", description = "You have more to prove, and your next task will take you far, so for now the Gelkis will fight the Magram without you.\n\nThe earth whispers many secrets to those who listen.  One secret I hear is of a red crystal.  It is called draenethyst, and it is new to our earth.  It comes from a place where mountains fly, and where demons rule.\n\nBring me a shard of draenethyst, and it will make my magic strong!  The shard is in a place called the Swamp of Sorrows, held by the lost one Ongeku.", progress = "Show me you are a friend of the Gelkis, {name}.", completion = "Yes, this is the shard of which the earth whispered.  I can feel strong magic in it!  I will use this magic against the enemies of the Gelkis.\n\nYou have done one more task for us, {name}.  Maybe soon, we will call you friend.", objectives = "Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1374] = { id = 1374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Jehn", description = "The earth speaks to me, and it says that the Magram grow weak.  Now it is time to kill their Khan!\n\nBring me the head of the Magram Khan, Jehn!", progress = "Show me you are a friend of the Gelkis, {name}.", completion = "Khan Jehn was strong, but stupid.  He thought his own strength was great.  He did not see that earth magic is stronger.  The Magram centaur will now fall without their leader, and the Gelkis will one day rule!", objectives = "Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1375] = { id = 1375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Shaka", description = "You help the Magram, and I like you.  Now, kill the Khan of the Gelkis!  He is Khan Shaka, and I want his head!  I want to stare at his head and laugh at him!", progress = "Do tasks for the Magram, and I will help you.", completion = "Khan Shaka is dead!  I will place his head on a pike, and keep it with me so Shaka can see the strength of the Magram!", objectives = "Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1380] = { id = 1380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Hratha", description = "{name}, you helped us against the Magram.  Now, help us beat the Maraudine!  Kill the head of their clan, Khan Hratha!\n\nTo face him, blow the Maraudine War Horn.  It is atop a high bluff in the Valley of Spears.\n\nBut to blow the horn, you must gain a warhorn mouthpiece.  These are rare, carried only by trusted Maraudine centaur.\n\nAfter the horn is blown, centaur will come.  Kill them until Hratha appears.\n\nKhan Hratha holds the piece of... a key.  Bring it to me...", progress = "Is Khan Hratha dead?  Do you have the key fragment?", completion = "He is dead!  Khan Hratha is dead!  And now the Maraudine will fall!  When the Gelkis rule this land, {name}, we will remember you.  And the spirits of the earth will sing your name for all time.", objectives = "Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1381] = { id = 1381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Hratha", description = "The Gelkis Khan is dead, and now the Maraudine will fall!  Kill the Maraudine Khan, Hratha!\n\nTo face him, blow the horn on the high bluff in the Valley of Spears.  But to blow the horn, you need a mouthpiece.  To get a mouthpiece, kill Maraudine centaur.  Keep killing until you find a mouthpiece.  Then blow the horn.\n\nDo this and Maraudine centaur will come to the tower.  Kill them until Khan Hratha appears.  Hratha holds the piece of a key.  Give this piece to me...", progress = "Do what I ask.  Prove to me that you are an ally of the Magram!", completion = "Khan Hratha is dead!  Now the Magram are the strongest of the centaur!  We will crush the others, and rule Desolace!\n\nWe will remember, you, {name}, and you will be spared our hooves when all others are trampled.", objectives = "Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1382] = { id = 1382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Alliance", description = "We are fortunate the centaur clans fight among themselves, for if they joined into a single force then they would be unstoppable.  Yes, we are fortunate, and we should press our advantage.\n\nOne of the centaur clans, the Gelkis clan, is in brutal war with the Magram clan.  If we attack the Magram, then perhaps an alliance may be struck with the Gelkis.\n\nSpeak with Uthek the Wise, in the outskirts of the Gelkis camps in southwestern Desolace.  Through her we might strike an alliance with the Gelkis.", completion = "Your name is whispered among the Gelkis.  You have much Magram blood on your hands.  This is good.\n\nMaybe it is also good if we speak.  Speak of what you can do for the Gelkis, and what we can do for you.", objectives = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1383] = { id = 1383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing But The Truth", description = "I have just the right serum in mind. It will deal with the truth in precisely the way the truth should be dealt with.\n\nFor this concoction I will need several Shadow Panther hearts from the Swamp. I also require the enchanted fungus off of the Mire Lord who resides there. I am sure one as able as you, {name}, can persuade him to part with some.\n\nThe last item I'll need for the serum is the blood of a dreaming whelp, like the ones that live outside Itharius' cave in the swamp.\n\nNow, off you go!", progress = "That Infiltrator in Stonard will surely.... open up... after he drinks my special serum. Haha!\n\nThe ingredients required are by no means easy to procure. Shadow Panthers are common in the Swamp but collecting enough hearts for our purpose can be daunting. And the Mire Lord can be such a fussy beast.", completion = "Splendid, {name}! And just in time too. From what Zraedus tells me, the Infiltrator has recovered from his wounds and is ready to be questioned by the orcs.\n\nGive me but a moment to prepare the pois-- I mean prepare the truth serum.", objectives = "Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and some Green Whelp Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1384] = { id = 1384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid on the Kolkar", description = "The Kolkar centaurs think their magic is strong.  They do not know magic!  They would not know magic if it bit them!\n\nYou will show them their magic is weak.  Go to the Kolkar  to the northeast and kill them.  Take their charms.  Bring me the charms and I will throw them in the fire and laugh!", progress = "You have the charms?  You showed the Kolkar they are weak?", completion = "You do a good thing for the Gelkis.  The Kolkar are weak and will die.  Their magic is pathetic and will not save them.  You showed them this, and their fear will make them even more feeble!\n\nAnd in our lands, the feeble soon die.", objectives = "Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1385] = { id = 1385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Politics", description = "Desolace is a land at war.  The centaurs wage war with each other, and we believe the victor among them will spill out and threaten our strongholds.  That, we cannot allow\n\nWe must learn how to beat the centaurs, and to do that... we must ally with one of the clans.  The Magram centaurs war with the Gelkis.  If you fight the Gelkis then the Magram might consider an alliance.\n\nEarn the favor of the Magrams then speak with Warug, in the Magram village in southeastern Desolace.", completion = "Many Gelkis fall to you.  I like that.  Maybe you can do more things I like.  Maybe you and the Magram can be friends.", objectives = "Gain a Friendly reputation with the Magram, then speak with Warug.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1386] = { id = 1386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Kolkar", description = "The Kolkar think they are strong, but we laugh at them!  We laugh and we kill them!  You kill them too.  Show me you can kill Kolkar like we do. Head north and slay them all!", completion = "The Kolkar fear you now!  I hope you laughed when you killed them.  It is better to laugh when you kill, so the enemy can see he is weak.", objectives = "Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1387] = { id = 1387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Centaur Bounty", description = "Many clans make up the centaur race.  Each has its own leader and agenda, but all the clans have one thing in common.  Cruelty.\n\nIf we are to ever find peace, then the centaurs must be removed.  And so I put you on the task to do just that.\n\nWhile wandering Desolace, hunt centaur and take their ears.  Bring me many, many ears.\n\nDo this in service of the Alliance, {name}, and we will be one step closer to war's end.", progress = "Do you have a report, {name}?", completion = "Ah, the ears.  Well done.\n\nYour service to the Alliance is unquestioned, {name}.  The blood you spilled in Desolace will, no doubt, save countless lives.", objectives = "Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1388] = { id = 1388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing But The Truth", description = "Everything is proceeding according to plan, {name}. I want you to give this truth serum to Deathstalker Zraedus and he'll show you how to administer it.... properly.\n\nHaha!", progress = "I hope you have proven yourself of use to our dear friend, Apothecary Faustin.", completion = "I knew old Faustin would come up with something good! You were a tremendous help, no doubt.\n\nNow let's get down to business, shall we?", objectives = "Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1389] = { id = 1389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "raenethyst Crystals", description = "The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the east, catching or killing any who wander near.\n\nAnd they have stolen something sacred to us--draenethyst crystals.\n\nWe lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.", progress = "Do you have the crystals?", completion = "Thank you, {name}.  We, are in your debt.", objectives = "Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1391] = { id = 1391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing But The Truth", description = "We need to operate with a certain amount of discretion. After all, it's not like you're going to waltz in there and convince the fool to drink Faustin's concoction here, right?\n\nBut if there's one thing those humans cannot deny it's the booze. I'll take Faustin's serum and mix it into this ale. I guarantee the poor sap will show no reluctance when it comes to chug-a-lugging a brew.\n\nMake haste to Stonard in the Swamp of Sorrows, {name}. And keep our little mission nice and quiet...", progress = "Please have mercy on me! I have information that goes beyond alliance boundaries. While I am no sympathizer of the Horde, there is political treachery going on that must be revealed!", completion = "A drink for me? How kind. It's been days since they've allowed me to drink. Let me drink this down and then I'll tell you what I've learned....", objectives = "Take Zraedus's Brew to Infiltrator Marksen in Stonard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1392] = { id = 1392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noboru the Cudgel", description = "Noboru has plagued the Draenei of the Harborage for months, and his cudgel is a symbol of the brutality they have suffered at the hands of the lost ones.", progress = "Greetings.  And welcome to the Harborage.", completion = "You have gained the weapon of the dreaded Noboru?  Is he then dead?\n\nThis is a joyous day for the Harborage.  Noboru and his gang were a terror to us, wandering the swamps and killing any Draenei who crossed his path.  He was a direct threat to our survival, and we did not have the strength to face him.\n\nWe are fortunate to have a friend in you, {name}.", objectives = "Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1393] = { id = 1393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galen's Escape", description = "Please help!  These creatures are going to eat me!\n\nHelp me out of here, and I'll give you a great treasure!  It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know.\n\nIf you help me escape, then I'll teach it to you.", completion = "The keyhole of this strongbox is filled with black resin.  It is impossible to open.\n\nBut Galen told you of a hidden latch on the box's bottom... \n\n...After a quick search the latch is found.  The latch is flipped, and the strongbox opens...", objectives = "Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1394] = { id = 1394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Passage", description = "You have done well, {name}. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles. He will sense the change within you, and see that your mind, body and spirit are strong enough that you should be rewarded for your efforts.\n\nStay true to the balance you've shown throughout these trials, {name}. Dorn will test you again in the future if you do.", sourceObjective = "Speak to Dorn Plainstalker in Thousand Needles.", completion = "Ah, {name}. It has been a long time since you have last stepped into my home. It seems like many moons have passed since you took your first leap that set you upon your path.\n\nAnd now you return to me stronger than you once were... more enlightened. This pleases me. And you should be justly rewarded for seeing my tests to the end.", sourceObjectiveStatus = "unverified-source-field" }
quests[1395] = { id = 1395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies for Nethergarde", description = "This crate of powerstones needs to go to Nethergarde Keep, in the Blasted Lands.  They won't hold their power for long, so we can't ship them with the next caravan.\n\nYou must take them, and you must take them quickly.\n\nBring them to Quartermaster Lungertz in Nethergarde Keep.  To reach the keep, you must travel east through Deadwind Pass, then east through the Swamp of Sorrows, then south through the Blasted Lands.\n\nUse caution, {name}.  You will travel through dangerous lands, yet you must not fail.", progress = "Hello!  Don't mind all the commotion, it's just business as usual at Nethergarde Keep.\n\nYou have something for me?", completion = "Ah, the powerstones!  The mages will be happy to see these!\n\nMany thanks, {name}.  I know your trip from Darkshire was not an easy one.", objectives = "Bring the Crate of Powerstones to Quartermaster Lungertz, before the powerstones expire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1396] = { id = 1396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ncroaching Wildlife", description = "My caravan was destined for the eastern coast, but we did not reach our goal.  Lost Ones attacked us, killing guards and dashing supplies.\n\nI alone survived their assault.  I have sworn to protect what supplies remain, but wild creatures skulk near.  Please, help me defend my camp from the beasts!", completion = "The sounds of animals are now faint, more distant.  Thank you, {name}.  Now let's hope they don't return!", objectives = "Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1398] = { id = 1398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "riftwood", description = "I owe you greatly, {name}.  An honorable heart beats within you.  And now I have another task for which I humbly ask your aid.\n\nIf I'm ever to reach Nethergarde, then I must fix this wagon.  And for that... I will need wood.  Strong, dry wood--not the spongy, tangled wood of the swamp's trees.\n\n{name}, go east to the coast and search for driftwood that has been dried by the sun.  Bring it to me.", progress = "Did you find any driftwood, {name}?", completion = "This wood is light, but tough.  Thank you, {name}.  It will work nicely.", objectives = "Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1418] = { id = 1418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeka Bloodscar", description = "The Badlands is harsh and lies close to the Alliance-held land of Loch Modan, so communication between Stonard and the Badlands outpost of Kargath is often cut.\n\nProve yourself, {name}.  Travel to the Badlands and speak with Neeka Bloodscar, head scout of the Kargath outpost.  Speak with her, and then send her report back to me.", completion = "Helgrum wants a report, eh?  I sent an outrunner to Stonard not three days past.  Did he fail his mission?  If Stonard does not have my report, then it appears he did fail.\n\nLet's hope the next runner I send has more skill, or more luck.", objectives = "Speak with Neeka Bloodscar.The Badlands is harsh and lies close to the Alliance-held land of Loch Modan, so communication between Stonard and the Badlands outpost of Kargath is often cut.\n\nProve yourself, {name}. Travel to the Badlands and speak with Neeka Bloodscar, head scout of the Kargath outpost. Speak with her, and then send her report back to me.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1419] = { id = 1419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coyote Thieves", description = "Have you spent many days in the Badlands, {class}?  Have you felt its heat? Have you faced the beasts that wander its dusty plains?  It's time you did.\n\nCrag coyotes are a tough breed.  Tough, and bold enough to creep into Kargath and steal from our food supplies.  Help rid the outpost of these thieves!\n\nHunt crag coyotes, {name}.  Hunt them and bring me their jawbones.  Bring me enough, and maybe I'll believe it when you say you know the Badlands.", progress = "Do you have the jawbones?", completion = "That's a nice collection of jawbones, {name}.  Now those coyotes won't be tearing through our supplies for scraps.\n\nWell done.  The coyotes of the Badlands aren't easy prey.  Your deed shows me that you might just survive here.", objectives = "Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1420] = { id = 1420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Helgrum", description = "I wrote a fresh report for Helgrum in Stonard.  Bring it to him.\n\nAnd if you consider yourself an outrunner, then don't lose your way.  Or fall to an enemy.", progress = "You returned.  You have a report?", completion = "Thank you, {name}.  From Neeka's report, I see the Alliance is not without its own problems.  And we may find that some enemies are shared between us.", objectives = "Bring Neeka's Report to Helgrum the Swift in Stonard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1421] = { id = 1421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Lost Caravan", description = "I was stunned during the attack by the Lost Ones, but before my sight went black I spied one of our wagons being dragged to the Fallow Sanctuary, the lost one village to the north.\n\nA caravan chest with valuable reagents was in that wagon, reagents vital to the studies of the wizards of Nethergarde Keep.  Find the chest and get those reagents, {name}.  Get them and bring them to me.", progress = "Do you have the wizard's reagents, {name}?", completion = "Ah, you found them!  With these, the wizards in Nethergarde may continue their work.  I do not know what it is that they do, but it is linked to the Dark Portal in the Blasted Lands, and is vital to the security of the Alliance.", objectives = "Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1422] = { id = 1422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "hreat From the Sea", description = "While I begin work on your weapon, why don't you talk to Katar? He mentioned needing help with patrols along the beach, and I'd rather see you keep your wits and weapons prepared instead of getting drunk with some of the other louses I share this camp with.", sourceObjective = "Speak to Katar in the Swamp of Sorrows.", completion = "Be silent a moment, {class}. Even over the dull roar of the sea you can still hear those disgusting gurgles from the fish men.", sourceObjectiveStatus = "unverified-source-field" }
quests[1423] = { id = 1423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Supplies", description = "This barrel is small yet sturdy.  Its seams are sealed with a yellow, pungent wax.  Stamped on the bottom of the barrel are the words:\n\nQUARTERMASTER LUNGERTZ\n\nNETHERGARDE KEEP", progress = "You have something for me?", completion = "Ah, thank you {name}!  So many supplies are lost from Darkshire to here.  It's good to see that some are recovered.", objectives = "Bring the Lost Supplies to Quartermaster Lungertz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1424] = { id = 1424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ool of Tears", description = "The Warchief sent us to investigate strange happenings at The Temple of Atal'Hakkar.\n\nThe Atal'ai trolls are a tribe of dark casters, known for practicing forbidden magic. You can imagine how astonished we were when we arrived here to discover the temple had been sunk.\n\nThe green dragons now guard the site, claiming to be protectors of Azeroth.\n\nWe need to discover what happened. Explore around the Pool of Tears and gather Atal'ai artifacts. From those I can begin to piece together this puzzle.", progress = "No one knows what dark practices went on inside The Temple of Atal'Hakkar. But we do know that great and powerful forces of magic were used.\n\nWe must learn as much as we can about such magic. Perhaps the spells of the Atal'ai will prove of use to the Horde.\n\nOnce you have gathered enough Atal'ai artifacts from around the Pool of Tears, I can begin to understand what the trolls were hoping to accomplish and what went so horribly wrong.", completion = "Your diligence in collecting the Atal'ai artifacts is worthy of praise, {class}.", objectives = "Fel'zerul in Stonard wants you to gather 5 Atal'ai Artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1425] = { id = 1425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eliver the Shipment", description = "While I fix this wagon, {name}, I have one last task for you.\n\nI have packed the most vital supplies saved from the ogre attacks.  Take them to Nethergarde Keep.  The keep is nestled in the northern hills of the Blasted Lands, keeping watch over the Dark Portal.\n\nTo reach Nethergard, follow the road east.  When it branches head south into the Blasted Lands, then turn left at the next fork.  Follow the road, {name}, and be wary.", progress = "You have business with me?", completion = "What?  A package from Biggs' caravan?  We thought it, and he, were lost.\n\nThank you, {name}.  With luck, these supplies will carry the much needed reagent, Azoran Crystals.  Our stock is running low...", objectives = "Bring the Shipment to Nethergarde to Quartermaster Lungertz in Nethergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1426] = { id = 1426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "hreat From the Sea", description = "I have no love for the sea, nor any creature I've seen come from its depths. It is a powerful but blind mistress; callous and brutal. It would bring me great pleasure to slay the fish men by the hundreds if it were within my power. But I garner some pleasure from watching their deaths at the hands of any who do the Horde's will.\n\nWhich brings us to you, {class}. How many can you slay? Would you test yourself against their most powerful kind?", completion = "The sea seems vast and relentless, but you have stained her with the blood of her own spawn. The fish men know pain. Their stupidity will force them to refortify their ranks from the devastation you've caused, and that is good.\n\nLet their gurgling screams overshadow the sea's roar long into the night. I shall smile every time I hear one of them silenced.\n\nReturn to me if you wish to slay more of the fish men. I will gladly reward you again.", objectives = "Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1427] = { id = 1427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "hreat From the Sea", description = "Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you. You would do well to test its strength against the fish men when you are ready... but only to please me further.", sourceObjective = "Speak with Tok'Kar in the Swamp of Sorrows.", completion = "Ah, {name}, you've returned. Good. I've finished crafting more weapons for our fight against the murlocs. For bringing us the fresh sawtooth meat, and for bringing a small smile to Katar's face, I offer one of them to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[1428] = { id = 1428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ontinued Threat", description = "It pleases me to see your hatred for the fish men grows with mine.\n\nFind more of their kind along the beach, and when you've had your fill of combat, return to me. We shall speak then of a reward for your diligence.", completion = "Well done, {class}. I call for more of their blood. Let all the fish men perish.", objectives = "Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
